window.SSAI_GUIDES=[{"subject":"論理国語","topic":"文章の構成と接続語","intro":"評論文などの論理的な文章は、主張を分かりやすく伝えるために決まった流れで組み立てられています。全体は「序論・本論・結論」に分けられることが多く、各部分をつなぐ役割を持つのが接続語です。接続語に注目すると、筆者の考えがどう展開していくかを追いやすくなります。このテーマでは、文章の基本的な構成と、接続語の働きを押さえましょう。","keywords":[{"word":"序論・本論・結論","meaning":"文章全体の基本構成。序論で問題や話題を提示し、本論で根拠や具体例を示して考えを展開し、結論で主張をまとめる。"},{"word":"順接","meaning":"前の内容を受けて、自然な流れで後の内容につなぐ関係。「だから」「そこで」などが使われる。"},{"word":"逆接","meaning":"前の内容から予想される流れに反する内容につなぐ関係。「しかし」「だが」などが使われる。筆者の主張が現れやすい場所でもある。"},{"word":"添加・並列","meaning":"前の内容に別の内容を付け加えたり、並べたりする関係。「また」「さらに」「および」などが使われる。"},{"word":"対比の接続語","meaning":"二つの事柄を比べる関係を示す。「一方」「これに対して」などが使われ、違いを際立たせる。"},{"word":"換言の接続語","meaning":"前の内容を別の言葉で言い換える関係。「つまり」「すなわち」などが使われ、その後に要旨が述べられることが多い。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"段落の役割と要旨","intro":"段落は、内容のまとまりごとに文章を分けた単位です。各段落には、全体の中で果たす役割（具体例を示す、理由を述べる、話題を転換するなど）があります。段落どうしの関係を整理すると、文章全体の要点である要旨をつかむことができます。このテーマでは、段落の役割の見分け方と、要旨のまとめ方を学びます。","keywords":[{"word":"段落","meaning":"一つの内容のまとまりを表す文章の単位。改行して書き始め、ふつう一つの段落には中心となる内容が一つ入る。"},{"word":"中心文","meaning":"段落の内容をまとめた文。その段落で最も伝えたいことが書かれており、段落の最初や最後に置かれることが多い。"},{"word":"要旨","meaning":"文章全体の要点を短くまとめたもの。筆者の主張とその根拠の中心部分を取り出すことで作る。"},{"word":"具体例の段落","meaning":"抽象的な主張を分かりやすくするために、実際の例を示す段落。「たとえば」で始まることが多い。"},{"word":"話題の転換","meaning":"段落の変わり目で、話題が新しい方向へ移ること。「ところで」「次に」などの言葉が目印になる。"},{"word":"段落構成図","meaning":"各段落の役割と段落どうしの関係を図に整理したもの。文章の論理の流れを一目で確かめるのに役立つ。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"論理の展開と根拠","intro":"論理的な文章では、主張がただ述べられるのではなく、根拠によって支えられています。根拠には、事実のデータ、具体例、専門家の意見などがあり、主張とのつながりの確かさが大切です。このテーマでは、主張と根拠の関係、根拠の種類、論理の飛躍の見分け方を学びます。","keywords":[{"word":"主張","meaning":"筆者が最も伝えたい考えや意見。文章の結論部分に置かれることが多い。"},{"word":"根拠","meaning":"主張を支える理由や証拠。事実、データ、具体例などが使われ、主張との関連が強いほど説得力が増す。"},{"word":"帰納法","meaning":"いくつかの具体的な事例から、共通する一般的な結論を導く考え方。"},{"word":"演繹法","meaning":"一般的な原則や前提から、個別の結論を導く考え方。前提が正しければ結論も正しくなる。"},{"word":"論理の飛躍","meaning":"根拠から結論へ進む途中で、必要な説明や証拠が不足していること。説得力を弱める原因になる。"},{"word":"事実と意見","meaning":"事実は確かめられる事柄、意見は人の考えや判断。文章を読むときは両者を区別することが大切。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"対比と例示","intro":"筆者は自分の考えをはっきりさせるために、対比と例示という方法をよく使います。対比は二つのものを比べて違いを際立たせる方法、例示は具体例を挙げて説明を分かりやすくする方法です。この二つの働きが分かると、文章のどこが主張の中心なのかが見えてきます。","keywords":[{"word":"対比","meaning":"性質の異なる二つの事柄を並べて比べ、違いを際立たせる表現方法。「一方」「に対して」が目印になる。"},{"word":"二項対立","meaning":"物事を二つの対立する側面に分けて考える枠組み。単純化しすぎると大事な点を見落とすこともある。"},{"word":"例示","meaning":"抽象的な説明に具体例を添えて、理解しやすくすること。「たとえば」「具体的には」が目印になる。"},{"word":"対照実験的な説明","meaning":"条件の違う二つの場合を比べて示す説明の仕方。違いの原因を考えさせる働きがある。"},{"word":"類比","meaning":"似た別の事柄になぞらえて説明する方法。たとえ話がこれにあたる。"},{"word":"具体と抽象の往復","meaning":"具体例でイメージを作り、抽象的な原則にまとめ直す読み方・書き方の基本的な動き。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"抽象と具体","intro":"言葉には、個別のものを指す具体的な言葉と、多くのものに共通する性質をまとめた抽象的な言葉があります。論理的な文章は、具体的な事例と抽象的な主張を行き来しながら組み立てられます。このテーマでは、抽象と具体の関係と、文章の中でその動きを読み取る方法を学びます。","keywords":[{"word":"抽象","meaning":"個々のものから共通する性質を取り出して、一般的に表すこと。「動物」「道具」などが抽象度の高い言葉。"},{"word":"具体","meaning":"実際に目に見えたり思い浮かべたりできる、個別のものを表すこと。「飼っている犬のポチ」などが具体的。"},{"word":"上位概念と下位概念","meaning":"「くだもの」は上位概念、「りんご」「みかん」は下位概念。抽象度の高低で言葉を整理する考え方。"},{"word":"一般化","meaning":"個別の事例から共通の傾向を取り出して、広く当てはまる言い方にすること。行き過ぎると誤りになりやすい。"},{"word":"抽象化の落とし穴","meaning":"抽象的な言葉だけで話が進み、実際の内容が伴わないこと。具体例で確かめることが大切。"},{"word":"定義","meaning":"言葉の意味をはっきり定めること。論理的な文章では、重要な言葉の定義から議論が始まることが多い。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"日本の近代文学の流れ","intro":"明治時代、日本の文学は西洋文学の影響を受けて大きく変わりました。言文一致の試みから写実主義・ロマン主義が生まれ、自然主義が主流となり、その後さまざまな文学の流れが登場します。このテーマでは、明治から昭和にかけての文学思潮の流れと、代表的な作家・作品の対応を押さえましょう。","keywords":[{"word":"言文一致","meaning":"話し言葉に近い文体で小説を書こうとする運動。二葉亭四迷の「浮雲」がその試みとして知られる。"},{"word":"坪内逍遥","meaning":"「小説神髄」で写実主義を唱え、近代文学の理論面を切り開いた人物。"},{"word":"写実主義","meaning":"現実をあるがままに描こうとする文学の立場。ロマン主義とともに明治文学の出発点となった。"},{"word":"ロマン主義","meaning":"個人の感情や理想を重視する文学の流れ。森鴎外や北村透谷らが関わった。"},{"word":"自然主義","meaning":"現実を客観的に観察し、人間の姿をありのままに描こうとする流れ。島崎藤村の「破戒」が代表作。"},{"word":"白樺派","meaning":"人道主義・理想主義を掲げた同人誌「白樺」の一派。武者小路実篤や志賀直哉が中心となった。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"明治の作家たち","intro":"明治時代には、日本の近代文学を築いた作家たちが次々に登場しました。夏目漱石や森鴎外は国民的作家として大きな影響を与え、樋口一葉や島崎藤村らも独自の世界を切り開きました。このテーマでは、代表的な作家と代表作の組み合わせを確実に覚えましょう。","keywords":[{"word":"夏目漱石","meaning":"「吾輩は猫である」「坊っちゃん」「こころ」などを書いた明治の国民的作家。朝日新聞に連載した作品が多い。"},{"word":"森鴎外","meaning":"軍医として働きながら文学活動をした作家。「舞姫」で文壇に登場し、後に「山椒大夫」などの歴史小説も書いた。"},{"word":"樋口一葉","meaning":"「たけくらべ」「にごりえ」で知られる女性作家。24歳で亡くなったが、明治文学に大きな足跡を残した。"},{"word":"島崎藤村","meaning":"詩集「若菜集」でロマン主義詩人として出発し、小説「破戒」で自然主義文学の代表作を残した。"},{"word":"二葉亭四迷","meaning":"「浮雲」で言文一致体に挑んだ作家。ロシア文学の翻訳でも知られる。"},{"word":"国木田独歩","meaning":"「武蔵野」などで自然を描いた作家。自然主義への橋渡しをした人物とされる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"大正・昭和の文学","intro":"大正時代には、白樺派や新思潮派など多様な文学が生まれ、昭和に入るとプロレタリア文学やモダニズム文学が登場しました。戦後は戦後派の作家が活躍し、やがて三島由紀夫や大江健三郎らが世界的に評価されるようになります。このテーマでは、大正から昭和の主な流れと代表作を整理しましょう。","keywords":[{"word":"志賀直哉","meaning":"白樺派の中心作家。「城の崎にて」「暗夜行路」で知られ、「小説の神様」とも呼ばれた。"},{"word":"芥川龍之介","meaning":"「羅生門」「鼻」などの短編で知られる新思潮派の作家。古典を題材にした作品も多い。"},{"word":"プロレタリア文学","meaning":"労働者や社会問題を題材に、社会の変革を目指した文学。小林多喜二の「蟹工船」が代表作。"},{"word":"太宰治","meaning":"「走れメロス」「人間失格」で知られる作家。戦後の若者に大きな影響を与えた。"},{"word":"川端康成","meaning":"「雪国」「伊豆の踊子」で知られ、日本人初のノーベル文学賞を受賞した作家。"},{"word":"三島由紀夫","meaning":"「仮面の告白」「金閣寺」などで知られる戦後の代表的作家。世界的にも高く評価された。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"詩・短歌・俳句","intro":"詩・短歌・俳句は、日本で長く親しまれてきた短い形式の文学です。短歌は五七五七七、俳句は五七五の音数で作られ、俳句には季語を入れる約束があります。近代以降は、自由な形式の詩や、口語で作る短歌・俳句も生まれました。このテーマでは、各形式の約束事と代表的な歌人・俳人を押さえましょう。","keywords":[{"word":"短歌","meaning":"五七五七七の31音で作る日本の伝統的な短詩形。与謝野晶子や石川啄木が近代短歌で活躍した。"},{"word":"俳句","meaning":"五七五の17音で作る世界で最も短い詩形の一つ。季語を入れるのが基本の約束。"},{"word":"季語","meaning":"季節を表す言葉。俳句では、どの季節の句かを表すために入れる。歳時記にまとめられている。"},{"word":"与謝野晶子","meaning":"歌集「みだれ髪」で知られる歌人。情熱的な恋の歌で近代短歌に新風を吹き込んだ。"},{"word":"正岡子規","meaning":"俳句と短歌の革新を進めた明治の文学者。写生を重んじ、近代俳句の基礎を作った。"},{"word":"口語詩","meaning":"話し言葉に近い言葉で書かれる詩。萩原朔太郎の「月に吠える」は口語自由詩の代表作。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"古典文学の基礎","intro":"日本の古典文学には、物語・日記・随筆・和歌などさまざまなジャンルがあります。平安時代には「源氏物語」や「枕草子」が生まれ、鎌倉時代には軍記物語や随筆の名作が登場しました。このテーマでは、代表的な古典作品と作者、成立した時代の対応を覚えましょう。","keywords":[{"word":"源氏物語","meaning":"平安時代に紫式部が書いた長編物語。光源氏を主人公とする世界最古級の長編小説とされる。"},{"word":"枕草子","meaning":"平安時代に清少納言が書いた随筆。「春はあけぼの」で始まる段が有名。"},{"word":"竹取物語","meaning":"現存する日本最古の物語とされる作品。かぐや姫の物語で、「物語の出で来はじめの祖」と評された。"},{"word":"平家物語","meaning":"鎌倉時代に成立した軍記物語。平家の繁栄と滅亡を描き、琵琶法師によって語り伝えられた。"},{"word":"徒然草","meaning":"鎌倉時代末期に吉田兼好が書いた随筆。243段からなり、無常観が表れている。"},{"word":"万葉集","meaning":"現存する日本最古の歌集。奈良時代末期に成立し、天皇から庶民まで幅広い人の歌が収められている。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"日本史","topic":"江戸幕府の成立","intro":"1600年の関ヶ原の戦いで勝利した徳川家康は、1603年に征夷大将軍に任命され、江戸に幕府を開きました。幕府は大名を親藩・譜代・外様に分けて配置し、武家諸法度や参勤交代によって大名を統制しました。また、キリスト教の禁止や貿易の制限を進め、幕藩体制と呼ばれる支配のしくみを整えていきました。このテーマでは、幕府の成立過程と大名統制・対外政策の基本を押さえましょう。","keywords":[{"word":"徳川家康","meaning":"関ヶ原の戦いに勝利し、1603年に征夷大将軍となって江戸幕府を開いた人物。"},{"word":"関ヶ原の戦い","meaning":"1600年、徳川家康の東軍と石田三成らの西軍が戦った天下分け目の戦い。家康が勝利した。"},{"word":"大坂の陣","meaning":"1614〜15年、幕府が大坂城の豊臣秀頼を攻めた戦い。これにより豊臣家は滅亡した。"},{"word":"武家諸法度","meaning":"幕府が大名の守るべき決まりを定めた法令。城の修理や婚姻にも幕府の許可が必要とされた。"},{"word":"参勤交代","meaning":"大名が1年おきに江戸と領地を行き来する制度。3代将軍家光のときに武家諸法度で義務づけられた。妻子は江戸に住んだ。"},{"word":"鎖国","meaning":"幕府が対外関係を制限した政策を指す言葉。貿易は長崎などでオランダ・中国などに限られ、完成は1639年ごろとされる。"}],"diagram":{"type":"timeline","title":"江戸幕府の成立の流れ","items":[{"label":"1600年","sub":"関ヶ原の戦いで家康が勝利"},{"label":"1603年","sub":"家康が征夷大将軍になり江戸幕府を開く"},{"label":"1615年","sub":"大坂の陣で豊臣家が滅亡"},{"label":"1635年","sub":"参勤交代が制度として定められる"}]},"illustration":"castle","story_intro":"関ヶ原の戦いに勝った徳川家康が江戸に幕府を開き、長い安定の時代が始まります。大名は親藩・譜代・外様に分けられ、武家諸法度や参勤交代で統制されました。こうして整えられた支配の仕組みは、幕藩体制と呼ばれます。キリスト教の禁止や貿易の制限も進み、幕藩体制が固まっていく物語です。"},{"subject":"日本史","topic":"明治維新","intro":"1853年にペリーが来航すると、日本は開国し、やがて幕府を倒す運動が高まりました。1867年の大政奉還で江戸幕府は終わり、新政府は明治維新と呼ばれる一連の改革を進めます。廃藩置県や地租改正、殖産興業などによって、近代国家の土台が作られました。このテーマでは、幕末から明治初期の大きな流れを押さえましょう。","keywords":[{"word":"ペリー来航","meaning":"1853年、アメリカのペリーが浦賀に来航し、日本に開国を求めた出来事。"},{"word":"日米和親条約","meaning":"1854年に結ばれた条約。下田と函館を開港し、日本は開国した。"},{"word":"大政奉還","meaning":"1867年、将軍徳川慶喜が政権を朝廷に返したこと。これにより江戸幕府は終わった。"},{"word":"廃藩置県","meaning":"1871年、藩を廃止して県を置き、知事を政府が任命した改革。中央集権化が進んだ。"},{"word":"地租改正","meaning":"1873年から行われた税制改革。土地の価格（地価）の3%を現金で納める形にし、政府の財政を安定させた。"},{"word":"殖産興業","meaning":"政府が産業を育てて国を豊かにしようとした政策。官営工場の設立などが進められた。"}],"diagram":{"type":"timeline","title":"幕末から明治維新へ","items":[{"label":"1853年","sub":"ペリーが浦賀に来航"},{"label":"1867年","sub":"大政奉還で江戸幕府が終わる"},{"label":"1871年","sub":"廃藩置県で県を置く"},{"label":"1873年","sub":"地租改正が始まる"}]},"illustration":"ship","story_intro":"ペリーの来航に日本中が揺れ、やがて幕府を倒す運動が高まります。大政奉還で江戸幕府は終わり、新政府は廃藩置県や地租改正、殖産興業など近代国家への改革を進めました。人々の暮らしや身分のあり方も、大きく変わっていきました。身分や暮らしが大きく変わる、変革の物語をたどりましょう。"},{"subject":"日本史","topic":"縄文・弥生時代","intro":"縄文時代は、縄文土器を使う狩猟・採集の時代で、1万年以上続きました。人々は竪穴住居に住み、貝塚を作るなど、自然の恵みに頼る生活を送っていました。続く弥生時代には、大陸から稲作と金属器が伝わり、社会に貧富の差や争いが生まれ、小さな国々ができていきます。このテーマでは、二つの時代の特徴の違いを押さえましょう。","keywords":[{"word":"縄文土器","meaning":"縄文時代に使われた、表面に縄目の文様がある厚手の土器。煮炊きに使われた。"},{"word":"貝塚","meaning":"縄文時代の人々が食べた貝殻などを捨てた跡。当時の食生活や環境を知る手がかりになる。"},{"word":"三内丸山遺跡","meaning":"青森県にある縄文時代の大規模な集落跡。大型の建物跡などが見つかっている。"},{"word":"弥生土器","meaning":"弥生時代に使われた、薄手で赤褐色の土器。縄文土器より高温で焼かれた。"},{"word":"稲作の伝来","meaning":"弥生時代の初めごろ、大陸や朝鮮半島から水田稲作が伝わり、食料の生産が始まった。"},{"word":"吉野ヶ里遺跡","meaning":"佐賀県にある弥生時代の大規模な環濠集落の跡。物見やぐらや墳丘墓が見つかっている。"},{"word":"邪馬台国","meaning":"3世紀ごろ日本にあったとされる国。中国の史書「魏志倭人伝」に記され、女王卑弥呼が治めた。"}],"diagram":null,"illustration":null,"story_intro":"森の恵みを分け合い、土器を作って暮らした縄文の人々。やがて海の向こうから米作りと金属が届き、むら同士が争い、小さな国が生まれていく。1万年以上続いた穏やかな時代から、社会が大きく動き出す時代へ、物語は移っていきます。二つの時代の違いをたどりましょう。"},{"subject":"日本史","topic":"鎌倉幕府と武士の社会","intro":"12世紀末、源頼朝が鎌倉に幕府を開き、武士が政治を行う時代が始まりました。将軍と御家人は、土地の支配を認めてもらう見返りに軍事の奉仕をする「御恩と奉公」の関係で結ばれていました。13世紀には元寇（蒙古襲来）があり、幕府の力が弱まっていくきっかけにもなります。このテーマでは、鎌倉幕府のしくみと武士社会の特徴を押さえましょう。","keywords":[{"word":"源頼朝","meaning":"1192年に征夷大将軍に任命され、鎌倉幕府を開いたとされる武士の棟梁。"},{"word":"守護・地頭","meaning":"幕府が各地に置いた役職。守護は国ごとの治安維持、地頭は荘園や公領の管理を担当した。"},{"word":"御恩と奉公","meaning":"将軍が御家人の土地支配を認める「御恩」と、御家人が軍事的に仕える「奉公」からなる主従関係。"},{"word":"執権政治","meaning":"将軍を補佐する執権が実権を握った政治。北条氏が代々執権を務めた。"},{"word":"元寇","meaning":"1274年と1281年、元のフビライが日本へ攻めてきた出来事。暴風雨などもあって元軍は退いた。"},{"word":"御成敗式目","meaning":"1232年に北条泰時が定めた武家社会の法令。裁判の基準を示した。"}],"diagram":null,"illustration":null,"story_intro":"源頼朝が鎌倉に幕府を開き、武士が政治を行う時代が始まります。将軍と御家人は土地と軍役で結ばれ、やがて海の向こうから元が攻めてきます。13世紀には元寇があり、幕府の力は次第に弱まっていきます。御成敗式目で裁判の基準が作られ、武士の社会の形が定まっていく物語を追いましょう。"},{"subject":"日本史","topic":"戦国時代と織田・豊臣","intro":"応仁の乱の後、各地の戦国大名が領国を支配する戦国時代になりました。下剋上の風潮の中で力を伸ばした織田信長は、天下統一を目指して革新的な政策を行います。その事業は豊臣秀吉が引き継ぎ、全国統一を果たしました。このテーマでは、戦国時代の特徴と、信長・秀吉の代表的な政策を押さえましょう。","keywords":[{"word":"応仁の乱","meaning":"1467年に始まった内乱。将軍の後継争いなどが原因で、幕府の力が弱まり戦国時代のきっかけとなった。"},{"word":"下剋上","meaning":"身分の低い者が実力で上の者を倒して地位を奪うこと。戦国時代を象徴する言葉。"},{"word":"織田信長","meaning":"尾張の戦国大名。桶狭間の戦いで今川義元を破り、楽市・楽座などの政策で統一事業を進めた。"},{"word":"楽市・楽座","meaning":"市場の税を免除し、座（同業者組合）の特権を廃止して、商業を活発にしようとした信長の政策。"},{"word":"豊臣秀吉","meaning":"信長の後を継いで全国統一を果たした人物。太閤検地や刀狩を行った。"},{"word":"太閤検地","meaning":"秀吉が全国で行った土地調査。田畑の面積と収穫量を統一した基準で測り、年貢の基準を定めた。"},{"word":"刀狩","meaning":"1588年、農民から武器を取り上げた政策。兵農分離を進めるねらいがあった。"}],"diagram":null,"illustration":null,"story_intro":"応仁の乱の後、各地の大名が領国を治める戦国時代になりました。その中で織田信長が革新的な政策で頭角を現し、本能寺の変で倒れた後、豊臣秀吉が全国統一を果たします。楽市・楽座など、新しい経済の仕組みも取り入れられました。検地や刀狩で新しい支配の形が作られていく物語です。"},{"subject":"日本史","topic":"太平洋戦争と戦後","intro":"1941年に始まった太平洋戦争は、1945年に日本の敗戦で終わりました。戦後、日本は連合国軍に占領され、日本国憲法の制定や農地改革など大きな民主化改革が行われます。1951年のサンフランシスコ平和条約で独立を回復し、その後は高度経済成長を遂げました。このテーマでは、戦争の終わりから戦後の出発までの流れを押さえましょう。","keywords":[{"word":"太平洋戦争","meaning":"1941年、日本軍の真珠湾攻撃で始まったアメリカなどとの戦争。1945年に日本の敗戦で終わった。"},{"word":"ポツダム宣言","meaning":"1945年に連合国が出した、日本に降伏を求める宣言。日本はこれを受け入れて降伏した。"},{"word":"日本国憲法","meaning":"1946年に公布され、1947年に施行された憲法。国民主権・平和主義・基本的人権の尊重が三つの原則。"},{"word":"農地改革","meaning":"戦後の改革の一つ。地主の土地を政府が買い上げて小作人に安く売り、自作農を増やした。"},{"word":"サンフランシスコ平和条約","meaning":"1951年に結ばれた講和条約。これにより日本は独立を回復した（沖縄などはアメリカの統治下に残った）。"},{"word":"高度経済成長","meaning":"1950年代半ばから1970年代初めまで、日本の経済が年平均10%前後で大きく成長した時期。"}],"diagram":null,"illustration":null,"story_intro":"1941年に始まった太平洋戦争は、1945年に日本の敗戦で終わります。占領のもとで日本国憲法の制定や農地改革など大きな改革が行われ、サンフランシスコ平和条約で独立を回復しました。その後の日本は、高度経済成長へと向かっていきます。廃墟から再び歩き出す人々の物語です。"},{"subject":"世界史","topic":"フランス革命","intro":"18世紀末のフランスでは、財政危機と身分制社会への不満から革命が起こりました。1789年に人権宣言が出され、自由・平等を掲げる新しい社会づくりが始まりますが、その後は混乱や恐怖政治も起こります。最後にナポレオンが登場し、革命の成果をヨーロッパ各地へ広げました。このテーマでは、革命の原因からナポレオンまでの流れを押さえましょう。","keywords":[{"word":"旧体制（アンシャン・レジーム）","meaning":"革命前のフランスの身分制社会。聖職者（第一身分）と貴族（第二身分）が特権を持ち、平民（第三身分）が税を負担した。"},{"word":"三部会","meaning":"聖職者・貴族・平民の三身分からなる議会。1789年、財政危機のためにルイ16世が招集したことが革命のきっかけとなった。"},{"word":"バスティーユ襲撃","meaning":"1789年7月14日、パリの民衆がバスティーユ牢獄を襲撃した出来事。フランス革命の始まりとされる。"},{"word":"人権宣言","meaning":"1789年に出された「人間と市民の権利の宣言」。自由・平等・国民主権などをうたい、近代民主主義の基礎となった。"},{"word":"ロベスピエール","meaning":"革命の指導者の一人。恐怖政治を主導したが、1794年に失脚して処刑された。"},{"word":"ナポレオン","meaning":"1799年にクーデタで権力を握り、後に皇帝となった軍人。ナポレオン法典を制定し、革命の成果を各地に広げた。"}],"diagram":{"type":"timeline","title":"フランス革命の流れ","items":[{"label":"1789年","sub":"バスティーユ襲撃と人権宣言"},{"label":"1793年","sub":"ロベスピエールの恐怖政治"},{"label":"1799年","sub":"ナポレオンが権力を握る"},{"label":"1804年","sub":"ナポレオンが皇帝になる"}]},"illustration":null,"story_intro":"18世紀末のフランスは、財政危機と身分制社会への不満に揺れていた。1789年、人々は立ち上がり、人権宣言が自由と平等を掲げる新しい社会づくりを宣言する。しかしその道のりは混乱や恐怖政治を経る険しいものとなり、最後にナポレオンが登場する。革命の始まりから広がりまでの物語をたどってみよう。"},{"subject":"世界史","topic":"古代ギリシャとローマ","intro":"古代ギリシャでは、都市国家（ポリス）が数多く生まれ、アテネでは民主政が発達しました。続くローマは、地中海世界を統一する大帝国を築き、法律や建築など多くの遺産を残します。このテーマでは、アテネの民主政とローマ帝国の歩みの基本を押さえましょう。","keywords":[{"word":"ポリス","meaning":"古代ギリシャの都市国家。アテネやスパルタが代表的で、それぞれ独立して政治を行った。"},{"word":"アテネの民主政","meaning":"成人男性市民が民会で政治に参加した制度。ただし女性や奴隷は参加できなかった。"},{"word":"ペルシア戦争","meaning":"紀元前5世紀、ペルシア帝国の侵攻をギリシャのポリス連合が退けた戦争。"},{"word":"アレクサンドロス大王","meaning":"マケドニアの王。東方へ遠征して大帝国を築き、ヘレニズム文化が生まれるきっかけを作った。"},{"word":"ローマ帝国","meaning":"紀元前27年、オクタウィアヌスがアウグストゥスの称号を得て始まった帝政ローマ。地中海世界を支配した。"},{"word":"パクス・ロマーナ","meaning":"「ローマの平和」という意味。帝政初期の約200年間、帝国内が比較的平和で安定した時期を指す。"}],"diagram":null,"illustration":null,"story_intro":"山と海に囲まれた地中海のほとりで、小さな都市国家ポリスが数多く生まれた。アテネでは市民が集まって政治を決める民主政が花開き、やがてローマは地中海世界を統一する大帝国へと成長する。法律や建築など多くの遺産を残した二つの世界が、どのように生まれ、広がっていったのかを見ていこう。"},{"subject":"世界史","topic":"産業革命","intro":"18世紀後半、イギリスで産業革命が始まりました。蒸気機関などの新しい技術によって工場制機械工業が発達し、人々の働き方や暮らしは大きく変わります。産業革命はヨーロッパ各地やアメリカへ広がり、資本主義社会の成立を促しました。このテーマでは、産業革命がイギリスで始まった理由と、その影響を押さえましょう。","keywords":[{"word":"蒸気機関","meaning":"ワットが改良した動力機関。工場の機械や蒸気機関車・蒸気船に使われ、産業革命の原動力となった。"},{"word":"工場制機械工業","meaning":"工場に労働者を集め、機械を使って大量生産を行うしくみ。それまでの手工業に取って代わった。"},{"word":"綿工業","meaning":"産業革命が最初に進んだ産業分野。インド産綿布に対抗して、イギリスで機械化が進んだ。"},{"word":"資本主義","meaning":"生産手段を持つ資本家が労働者を雇い、利潤を追求する経済のしくみ。産業革命を背景に発達した。"},{"word":"労働問題","meaning":"長時間労働や低賃金、児童労働など、産業革命の進展とともに深刻化した問題。労働運動や社会主義思想の背景となった。"},{"word":"都市化","meaning":"工場のある都市へ人口が集中すること。衛生環境の悪化などの都市問題も生まれた。"}],"diagram":{"type":"flow","title":"産業革命の広がり","items":[{"label":"綿工業の機械化","sub":"紡績・織布の機械が登場"},{"label":"蒸気機関の改良","sub":"工場や交通の動力になる"},{"label":"工場制機械工業","sub":"工場で大量生産するしくみ"},{"label":"都市化と労働問題","sub":"都市へ人口が集中し問題も生まれた"}]},"illustration":"factory","story_intro":"18世紀後半のイギリスで、蒸気の力が工場を動かし始めた。新しい技術によって工場制機械工業が発達し、人々の働き方や暮らしは大きく姿を変えていく。この変化はヨーロッパ各地やアメリカへ広がり、資本主義社会の成立を促した。人々の生活を一変させた大変化は、なぜイギリスから始まったのだろう。"},{"subject":"世界史","topic":"中国の王朝","intro":"中国では、秦の始皇帝による統一以来、漢・唐・宋・元・明・清など多くの王朝が交代してきました。王朝の交代（易姓革命）や、科挙・冊封体制といったしくみは、東アジア全体に大きな影響を与えています。このテーマでは、代表的な王朝の順序と、それぞれの特徴を押さえましょう。","keywords":[{"word":"始皇帝","meaning":"紀元前221年に中国を統一した秦の王。皇帝の称号を初めて使い、文字や貨幣などを統一した。"},{"word":"漢","meaning":"劉邦が建てた王朝。武帝の時代に儒教が重んじられ、シルクロードを通じた交易も行われた。"},{"word":"唐","meaning":"7世紀に中国を統一した王朝。都の長安は国際都市として栄え、律令制や文化が日本にも影響を与えた。"},{"word":"科挙","meaning":"試験によって官僚を選ぶ制度。隋で始まり、唐・宋以降に整えられ、家柄より学力を重んじるしくみとなった。"},{"word":"元","meaning":"モンゴル人のフビライが建てた王朝。中国全土を支配し、日本へも遠征した（元寇）。"},{"word":"清","meaning":"満州族が建てた中国最後の王朝。19世紀にはアヘン戦争でイギリスに敗れ、半植民地化が進んだ。"}],"diagram":null,"illustration":null,"story_intro":"広大な大陸の東で、一つの王朝が倒れては新しい王朝が生まれる歴史が長く続いた。秦の始皇帝による統一以来、漢・唐・宋・元・明・清と王朝は交代し、そのしくみは東アジア全体に影響を与えていく。科挙や冊封体制といった工夫は、どのように国を治めるために生まれたのか。王朝の移り変わりの物語を追おう。"},{"subject":"世界史","topic":"ルネサンスと大航海時代","intro":"14世紀ごろ、イタリアを中心にルネサンス（文芸復興）の文化が花開きました。人間らしさを大切にする考え方が広がり、芸術や科学が大きく発展します。続く15世紀末からは、ヨーロッパ人が新しい航路を求めて大洋へ乗り出す大航海時代が始まり、世界は一つにつながっていきました。このテーマでは、二つの動きの基本を押さえましょう。","keywords":[{"word":"ルネサンス","meaning":"古代ギリシャ・ローマの文化を復興しようとする動き。「文芸復興」とも訳され、イタリアから広がった。"},{"word":"レオナルド・ダ・ヴィンチ","meaning":"「モナ・リザ」などで知られるルネサンス期の芸術家。科学や解剖学にも関心を持った万能の天才とされる。"},{"word":"宗教改革","meaning":"16世紀、ルターらがカトリック教会を批判して始めた改革運動。プロテスタントと呼ばれる新しい教会が生まれた。"},{"word":"コロンブス","meaning":"1492年、大西洋を横断してアメリカ大陸に到達した航海者。スペインの支援を受けた。"},{"word":"マゼラン","meaning":"世界一周航海を始めた航海者。途中で亡くなったが、船隊は1522年に世界一周を成し遂げた。"},{"word":"バスコ・ダ・ガマ","meaning":"1498年、アフリカ南端を回ってインドに到達したポルトガルの航海者。香辛料貿易の航路が開かれた。"}],"diagram":null,"illustration":null,"story_intro":"14世紀ごろ、イタリアの都市から新しい文化の風が吹き始めた。人間らしさを大切にするルネサンスの広がりとともに、芸術や科学は大きく発展していく。続く15世紀末、人々は新しい航路を求めて大洋へ乗り出し、世界は一つにつながり始めた。文化の開花と大航海、二つの大きな動きの物語をたどろう。"},{"subject":"世界史","topic":"第一次世界大戦","intro":"20世紀初め、ヨーロッパの列強は植民地をめぐって対立し、同盟と協商の二つの陣営に分かれていました。1914年のサラエボ事件をきっかけに第一次世界大戦が始まり、総力戦として世界中に広がります。戦争の後には国際連盟が作られましたが、平和は長く続きませんでした。このテーマでは、大戦の原因と結果の基本を押さえましょう。","keywords":[{"word":"三国同盟と三国協商","meaning":"ドイツ・オーストリア・イタリアの同盟と、イギリス・フランス・ロシアの協商。大戦前のヨーロッパの対立構造。"},{"word":"サラエボ事件","meaning":"1914年、オーストリアの皇位継承者が暗殺された事件。第一次世界大戦のきっかけとなった。"},{"word":"総力戦","meaning":"国民や経済の全てを戦争に動員する戦争の形。第一次世界大戦で本格化した。"},{"word":"ヴェルサイユ条約","meaning":"1919年に結ばれた第一次世界大戦の講和条約。ドイツに厳しい賠償や軍備制限を課した。"},{"word":"国際連盟","meaning":"1920年に設立された国際平和機構。本部はジュネーブ。アメリカが参加しなかったことなどが弱点となった。"},{"word":"ロシア革命","meaning":"1917年、大戦中にロシアで起きた革命。レーニンの指導で世界初の社会主義政権が生まれた。"}],"diagram":null,"illustration":null,"story_intro":"20世紀初めのヨーロッパは、植民地をめぐる対立の中で同盟と協商の二つの陣営に分かれ、緊張を高めていた。1914年、サラエボの一発の銃声が引き金となり、戦争は総力戦として世界中へ広がっていく。戦いの後には国際連盟が作られたが、平和への道は平坦ではなかった。大戦の原因と結果の物語をたどろう。"},{"subject":"倫理","topic":"ギリシャの哲学者たち","intro":"古代ギリシャでは、自然や人間について深く考える哲学が生まれました。ソクラテスは対話を通じて「無知の知」を説き、その弟子プラトンはイデア論を唱えました。さらにその弟子アリストテレスは、幅広い学問を体系化します。このテーマでは、三人の哲学者の考え方の違いと師弟関係を押さえましょう。","keywords":[{"word":"ソクラテス","meaning":"対話（問答法）によって相手に無知を自覚させ、真理を探ろうとした哲学者。「無知の知」で知られる。"},{"word":"無知の知","meaning":"自分が何も知らないことを自覚することが、知恵の始まりであるというソクラテスの考え。"},{"word":"プラトン","meaning":"ソクラテスの弟子。本当の実在は「イデア」であるとするイデア論を唱え、著書「国家」で理想の国制を論じた。"},{"word":"イデア","meaning":"感覚で捉えられるものの背後にある、完全な本質・真実在というプラトンの考え。"},{"word":"アリストテレス","meaning":"プラトンの弟子。論理学や自然学など多くの学問を体系化し、「万学の祖」と呼ばれる。"},{"word":"ソフィスト","meaning":"弁論術を教えた職業教師たち。「人間は万物の尺度」と唱えたプロタゴラスが代表的。相対主義的な考えを持った。"}],"diagram":{"type":"flow","title":"哲学者たちの師弟関係","items":[{"label":"ソクラテス","sub":"無知の知・問答法"},{"label":"プラトン","sub":"ソクラテスの弟子・イデア論"},{"label":"アリストテレス","sub":"プラトンの弟子・万学の祖"}]},"illustration":null,"story_intro":null},{"subject":"倫理","topic":"仏教の思想","intro":"仏教は、紀元前5世紀ごろのインドでゴータマ（釈迦）が開いた宗教・思想です。人生は苦しみであるという見方から出発し、苦しみの原因である煩悩をなくすことで悟りに至ると説きます。後に大乗仏教が広がり、日本にも伝わって大きな影響を与えました。このテーマでは、仏教の基本的な考え方を押さえましょう。","keywords":[{"word":"ゴータマ（釈迦）","meaning":"仏教の開祖。苦行の末に悟りを開き、人々に教えを説いた。ブッダ（目覚めた人）とも呼ばれる。"},{"word":"四苦八苦","meaning":"生・老・病・死の四苦など、人生につきまとう苦しみの総称。仏教の出発点となる見方。"},{"word":"煩悩","meaning":"欲望や怒りなど、心を惑わせて苦しみを生むはたらき。悟りの妨げとされる。"},{"word":"解脱","meaning":"煩悩による苦しみの束縛から解き放たれ、悟りの境地に至ること。"},{"word":"大乗仏教","meaning":"自分だけでなく多くの人々の救済を目指す仏教の流れ。菩薩の実践を重んじ、日本に伝わった仏教の中心となった。"},{"word":"縁起","meaning":"すべてのものは原因と条件によって生じ、互いに依存し合っているという仏教の根本的な考え。"}],"diagram":{"type":"causal","title":"仏教の考え方の流れ","items":[{"label":"四苦八苦","sub":"人生には苦しみがある"},{"label":"煩悩","sub":"苦しみの原因は心の迷い"},{"label":"修行","sub":"煩悩をなくす実践"},{"label":"解脱（悟り）","sub":"苦しみから解き放たれる"}]},"illustration":null,"story_intro":null},{"subject":"倫理","topic":"キリスト教とイスラム教","intro":"キリスト教とイスラム教は、ユダヤ教とルーツを同じくする一神教です。キリスト教はイエスの教えをもとに広がり、イスラム教はムハンマドが開いて中東から世界へ広がりました。どちらも唯一の神を信じ、人々の生き方や社会の仕組みに大きな影響を与えています。このテーマでは、二つの宗教の基本を押さえましょう。","keywords":[{"word":"イエス","meaning":"キリスト教の中心人物。神の愛と隣人愛を説き、十字架にかけられたと伝えられる。"},{"word":"隣人愛","meaning":"自分のように隣人を愛すること。イエスが説いたキリスト教の中心的な教え（アガペー）。"},{"word":"聖書","meaning":"キリスト教の聖典。旧約聖書と新約聖書からなる。新約聖書にはイエスの生涯や教えが記されている。"},{"word":"ムハンマド","meaning":"イスラム教の開祖で、神（アッラー）の預言者とされる。7世紀にアラビア半島で教えを広めた。"},{"word":"コーラン","meaning":"イスラム教の聖典。ムハンマドが神から受けたとされる啓示をまとめたもの。"},{"word":"五行","meaning":"イスラム教徒の義務とされる五つの実践。信仰告白・礼拝・喜捨・断食・巡礼を指す。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"倫理","topic":"日本の思想","intro":"日本では、古くからの神道や、伝わってきた仏教・儒教が互いに影響し合いながら思想が育ってきました。江戸時代には国学や朱子学が発達し、明治時代には西洋の思想が取り入れられます。このテーマでは、日本の思想の代表的な考え方と人物を押さえましょう。","keywords":[{"word":"神道","meaning":"日本古来の信仰。自然や祖先を神として敬い、八百万の神という考え方を持つ。"},{"word":"浄土信仰","meaning":"阿弥陀仏を信じて極楽浄土への往生を願う信仰。平安時代末から鎌倉時代にかけて広がった。"},{"word":"法然と親鸞","meaning":"法然は浄土宗、弟子の親鸞は浄土真宗を開いた鎌倉時代の僧。念仏による救済を説いた。"},{"word":"朱子学","meaning":"中国で朱熹が大成した儒学の一派。江戸幕府に重んじられ、身分秩序を支える思想となった。"},{"word":"本居宣長","meaning":"江戸時代の国学者。「古事記伝」を著し、日本古来の精神（大和心）を明らかにしようとした。"},{"word":"福沢諭吉","meaning":"明治時代の思想家・教育者。「学問のすゝめ」で人々の自立と学問の大切さを説いた。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"倫理","topic":"近代の哲学者","intro":"近代ヨーロッパでは、理性や経験を重んじる新しい哲学が生まれました。デカルトは近代哲学の出発点となり、カントは理性そのものを検討して認識の仕組みを明らかにします。19世紀にはニーチェが伝統的な価値観を問い直しました。このテーマでは、代表的な哲学者の考え方の要点を押さえましょう。","keywords":[{"word":"デカルト","meaning":"「我思う、ゆえに我あり」で知られる哲学者。すべてを疑う方法（方法的懐疑）から確実な知識を求めた。"},{"word":"合理論","meaning":"知識の源は理性にあるとする立場。デカルトが代表的。経験を重んじる経験論と対比される。"},{"word":"経験論","meaning":"知識は感覚の経験から得られるとする立場。ロックやヒュームが代表的。"},{"word":"カント","meaning":"合理論と経験論を統合しようとした哲学者。著書「純粋理性批判」で人間の認識の仕組みを検討した。"},{"word":"ベンサム","meaning":"功利主義を唱えた思想家。「最大多数の最大幸福」を社会の善の基準とした。"},{"word":"ニーチェ","meaning":"伝統的な道徳や宗教の価値を批判し、「神は死んだ」という言葉で知られる哲学者。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"日本国憲法の基本原則","intro":"日本国憲法は、国民主権・平和主義・基本的人権の尊重を三つの基本原則としています。国民主権では、政治の最終的な決定権は国民にあるとされ、人権は侵すことのできない永久の権利として保障されます。平和主義は第9条に表れ、戦争の放棄と戦力の不保持を定めています。このテーマでは、三原則の内容と、憲法の基本的な性格を押さえましょう。","keywords":[{"word":"国民主権","meaning":"国の政治のあり方を最終的に決める力（主権）は国民にあるという原則。憲法の前文と第1条に表れている。"},{"word":"平和主義","meaning":"戦争を放棄し、平和を守ろうとする原則。憲法第9条で戦争の放棄と戦力の不保持が定められている。"},{"word":"基本的人権の尊重","meaning":"人間が生まれながらに持つ権利を大切にする原則。第11条で「侵すことのできない永久の権利」とされる。"},{"word":"象徴天皇制","meaning":"天皇は日本国と国民統合の象徴であり、国政に関する権能を持たないとするしくみ。第1条に定められている。"},{"word":"立憲主義","meaning":"憲法によって国家権力を制限し、国民の権利を守るという考え方。憲法が国の最高法規であることと結びつく。"},{"word":"最高法規","meaning":"憲法は国の法の中で最も強い効力を持ち、憲法に反する法律や命令は効力を持たない（第98条）。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"国会・内閣・裁判所","intro":"日本の政治は、国会・内閣・裁判所の三権が互いに抑制し合う三権分立のしくみで成り立っています。国会は法律を作る立法機関、内閣は政治を行う行政機関、裁判所は法に基づいて判断する司法機関です。このテーマでは、三権それぞれの役割と関係を押さえましょう。","keywords":[{"word":"三権分立","meaning":"立法・行政・司法の三つの権力を別々の機関に分け、互いに抑制と均衡を図るしくみ。権力の集中を防ぐ。"},{"word":"国会","meaning":"衆議院と参議院からなる立法機関。「国権の最高機関」「国の唯一の立法機関」と憲法に定められている。"},{"word":"衆議院の優越","meaning":"予算や条約、内閣総理大臣の指名などで、衆議院の議決が参議院より優先されるしくみ。任期が短く解散があるため民意を反映しやすいと考えられている。"},{"word":"内閣","meaning":"行政権を担う機関。内閣総理大臣と国務大臣からなり、国会に対して連帯して責任を負う（議院内閣制）。"},{"word":"裁判所","meaning":"司法権を担う機関。最高裁判所と下級裁判所があり、法律が憲法に違反しないかを判断する違憲審査権を持つ。"},{"word":"議院内閣制","meaning":"内閣が国会の信任に基づいて成立し、国会に責任を負う制度。不信任決議が可決されれば内閣は総辞職か衆議院解散を選ぶ。"}],"diagram":{"type":"flow","title":"法律ができるまで","items":[{"label":"法律案の提出","sub":"議員または内閣が国会へ"},{"label":"委員会で審査","sub":"専門家から意見も聞く"},{"label":"本会議で議決","sub":"両議院で可決"},{"label":"法律の公布・施行","sub":"天皇が公布し、国民に知らせる"}]},"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"選挙と政党","intro":"民主政治では、選挙によって国民の代表が選ばれます。日本の選挙には、普通・平等・直接・秘密の四つの原則があり、衆議院では小選挙区比例代表並立制が採用されています。政党は、政治の考えを同じくする人々の集まりで、政権を担ったり野党として政府を監視したりします。このテーマでは、選挙制度と政党の役割を押さえましょう。","keywords":[{"word":"選挙の四原則","meaning":"普通選挙（一定年齢以上の全員に選挙権）、平等選挙（一人一票）、直接選挙（代表を直接選ぶ）、秘密選挙（投票の秘密を守る）。"},{"word":"小選挙区制","meaning":"一つの選挙区から一人だけを選ぶ制度。大政党に有利で政権交代が起こりやすい一方、死票が多くなる。"},{"word":"比例代表制","meaning":"政党の得票率に応じて議席を配分する制度。少数意見が反映されやすいが、小政党が乱立しやすい。"},{"word":"小選挙区比例代表並立制","meaning":"衆議院議員選挙で採用されている、小選挙区制と比例代表制を組み合わせた制度。"},{"word":"与党と野党","meaning":"与党は政権を担う政党、野党は政権に就いていない政党。与党と内閣を監視し、対案を示す役割を持つ。"},{"word":"一票の格差","meaning":"選挙区によって一票の価値に差が生じる問題。裁判で違憲状態と判断されたことがある。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"需要と供給","intro":"市場では、商品を買いたい人の量（需要）と売りたい人の量（供給）の関係によって価格が決まります。価格が上がれば需要は減って供給は増え、価格が下がればその逆になります。このテーマでは、需要曲線・供給曲線の読み方と、価格が決まる仕組みを押さえましょう。","keywords":[{"word":"需要","meaning":"ある価格で、消費者が買おうとする商品の量。ふつう価格が下がるほど需要量は増える。"},{"word":"供給","meaning":"ある価格で、生産者が売ろうとする商品の量。ふつう価格が上がるほど供給量は増える。"},{"word":"均衡価格","meaning":"需要量と供給量が一致するところで決まる価格。市場で実際に成立する価格の目安になる。"},{"word":"需要曲線","meaning":"価格と需要量の関係を表す右下がりの曲線（グラフ）。価格が下がると需要量が増える関係を示す。"},{"word":"供給曲線","meaning":"価格と供給量の関係を表す右上がりの曲線（グラフ）。価格が上がると供給量が増える関係を示す。"},{"word":"価格の自動調節機能","meaning":"需要と供給の不一致を、価格の変動によって自然に調整する市場の働き。「見えざる手」とも呼ばれる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"金融のしくみ","intro":"金融とは、お金に余裕のある人から不足している人へ、お金を融通することです。銀行は預金を受け入れ、それを企業などに貸し出す役割を担います。また、日本銀行は国の中央銀行として、紙幣の発行や金融政策を行います。このテーマでは、金融の基本的なしくみと日本銀行の役割を押さえましょう。","keywords":[{"word":"直接金融と間接金融","meaning":"直接金融は株式や債券で企業が直接資金を集める方法。間接金融は銀行などが間に入って貸し出す方法。"},{"word":"日本銀行","meaning":"日本の中央銀行。銀行券（紙幣）の発行、物価の安定、金融システムの安定が役割。「発券銀行」「銀行の銀行」「政府の銀行」と呼ばれる。"},{"word":"金融政策","meaning":"中央銀行が景気や物価を安定させるために行う政策。政策金利の上げ下げが代表的。"},{"word":"政策金利","meaning":"中央銀行が金融機関への貸し出しなどに用いる基準金利。景気が過熱すれば上げ、不況なら下げる。"},{"word":"株式","meaning":"株式会社が事業資金を集めるために発行する証券。買った人は株主となり、配当や株主総会での議決権を持つ。"},{"word":"預金保険制度","meaning":"銀行が破綻しても、預金者一人につき元本1000万円とその利息までを保護する制度。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"情報","topic":"ネットワークとセキュリティ","intro":"コンピュータどうしをつなぐネットワークでは、決められた約束事（プロトコル）に従ってデータがやり取りされます。インターネットでは、データを小さく分けて送る仕組みや、宛先を示すIPアドレスが使われます。また、不正アクセスやウイルスなどから情報を守るセキュリティの考え方も大切です。このテーマでは、ネットワークの基本と情報を守る方法を押さえましょう。","keywords":[{"word":"プロトコル","meaning":"ネットワークでデータをやり取りするための約束事・手順の決まり。TCP/IPが代表的。"},{"word":"IPアドレス","meaning":"ネットワーク上の機器を識別するための番号。インターネット上の住所のような役割を持つ。"},{"word":"パケット","meaning":"データを小さく分割した単位。パケット通信では、分割されたデータが別々の経路を通って届き、元に組み立てられる。"},{"word":"暗号化","meaning":"データを第三者に読めない形に変換すること。通信の盗み見や改ざんを防ぐ基本的な技術。"},{"word":"認証","meaning":"利用者が本人であることを確かめること。パスワードのほか、指紋などの生体認証や二要素認証がある。"},{"word":"コンピュータウイルス","meaning":"コンピュータに害を与える不正なプログラム。感染を防ぐにはセキュリティソフトの更新や不審なファイルを開かないことが大切。"}],"diagram":{"type":"flow","title":"パケット通信の流れ","items":[{"label":"データを分割","sub":"小さなパケットに分ける"},{"label":"ネットワークを転送","sub":"宛先のIPアドレスを頼りに進む"},{"label":"受信側で組み立て","sub":"順番をそろえて元に戻す"},{"label":"確認して完了","sub":"届かない分は再送する"}]},"illustration":null,"story_intro":null},{"subject":"情報","topic":"2進数と情報量","intro":"コンピュータは、電気のオン・オフを0と1に対応させ、すべての情報を2進数で表しています。文字や画像や音も、最終的には数字の列に変換されて処理されます。このテーマでは、2進数と10進数の変換や、ビット・バイトなどの情報量の単位を押さえましょう。","keywords":[{"word":"2進数","meaning":"0と1の2種類の数字だけで数を表す方法。コンピュータ内部の情報表現の基本。"},{"word":"ビット","meaning":"情報量の最小単位。0か1かのどちらか一方を表す。"},{"word":"バイト","meaning":"8ビットをまとめた単位。1バイトで英数字1文字程度を表せる。"},{"word":"16進数","meaning":"0〜9とA〜Fの16種類の記号で数を表す方法。2進数の4桁を1桁にまとめられるため、コンピュータの表記でよく使われる。"},{"word":"文字コード","meaning":"文字と数字（ビット列）の対応表。UTF-8やShift_JISなどの種類がある。"},{"word":"デジタル化","meaning":"音や画像などのアナログ情報を、数値の列に変換すること。標本化・量子化・符号化の手順で行われる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"情報","topic":"アルゴリズムとプログラミング","intro":"アルゴリズムとは、問題を解くための手順のことです。プログラムは、順次・分岐・反復という基本的な構造の組み合わせで作られます。手順を図で表すフローチャートを使うと、処理の流れが分かりやすくなります。このテーマでは、アルゴリズムの基本構造と、代表的な処理の考え方を押さえましょう。","keywords":[{"word":"アルゴリズム","meaning":"問題を解決するための明確な手順。同じ目的でも、手順によって効率が大きく変わることがある。"},{"word":"順次・分岐・反復","meaning":"プログラムの基本構造。順次は上から順に実行、分岐は条件で処理を選ぶ、反復は同じ処理を繰り返す。"},{"word":"フローチャート","meaning":"処理の流れを図記号で表したもの。開始・終了は端子、判断はひし形で表すなどの約束がある。"},{"word":"変数","meaning":"データを一時的に入れておく箱のようなもの。名前を付けて値を出し入れできる。"},{"word":"探索","meaning":"データの中から目的のものを探す処理。端から順に探す線形探索や、範囲を半分に絞る二分探索がある。"},{"word":"整列（ソート）","meaning":"データを大きい順や小さい順に並べ替える処理。バブルソートなどが基本として知られる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"情報","topic":"データの活用","intro":"社会には大量のデータが集まっており、それを整理・分析して役立てることが求められています。データをグラフや表に表すときは、目的に合った方法を選ぶことが大切です。また、平均値などの代表値や、相関関係の読み取り方にも注意点があります。このテーマでは、データ活用の基本を押さえましょう。","keywords":[{"word":"代表値","meaning":"データ全体の特徴を一つの値で表したもの。平均値・中央値・最頻値があり、外れ値があるときは中央値が実態を表しやすい。"},{"word":"散布図と相関","meaning":"二つの量の関係を点で表したグラフが散布図。点の集まり方から、正の相関・負の相関・相関なしを読み取る。"},{"word":"相関と因果","meaning":"相関関係があっても、必ずしも一方が原因とは限らない。安易に因果関係と決めつけないことが大切。"},{"word":"ビッグデータ","meaning":"従来の方法では扱いきれないほど大量で多様なデータ。AIの学習などにも使われる。"},{"word":"データベース","meaning":"データを整理して蓄え、検索や更新をしやすくした仕組み。表（テーブル）の形で管理する関係データベースが代表的。"},{"word":"オープンデータ","meaning":"誰でも自由に使える形で公開されたデータ。自治体の統計などがあり、二次利用が進められている。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"情報","topic":"情報社会と法律","intro":"情報技術の発達により、便利な社会になった一方で、新しい問題も生まれています。個人情報の扱い、著作権、SNSでの発言など、情報社会で守るべきルールや法律を知ることが大切です。このテーマでは、情報モラルと関係する法律の基本を押さえましょう。","keywords":[{"word":"個人情報","meaning":"氏名や生年月日など、特定の個人を識別できる情報。個人情報保護法で取り扱いのルールが定められている。"},{"word":"著作権","meaning":"著作物を作った人の権利。文章・音楽・画像などは、原則として著作者の許可なく勝手に使えない。"},{"word":"知的財産権","meaning":"著作権や特許権など、創作や発明に対する権利の総称。人間の知的活動の成果を守る。"},{"word":"情報モラル","meaning":"情報社会で守るべき道徳や心構え。他人への配慮や、法令・ルールの遵守を含む。"},{"word":"フェイクニュース","meaning":"事実でないのに本当らしく見せた情報。拡散する前に出典を確認する習慣が大切。"},{"word":"デジタルデバイド","meaning":"情報技術を使える人と使えない人の間に生じる格差のこと。情報格差ともいう。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"体育","topic":"安全の確保","intro":"スポーツは楽しいものですが、けがや事故の危険もともないます。安全にスポーツを行うためには、事故が起こる原因を知り、事前の点検や準備、環境への注意、正しい応急処置の方法を身につけることが大切です。このテーマでは、熱中症や落雷などの危険への備えと、けがをしたときの応急処置の基本を押さえましょう。","keywords":[{"word":"危険の予測と回避","meaning":"施設・用具の異常、天候の変化、体調の不良など、事故につながる危険を事前に察知し、取り除いたり避けたりすること。安全確保の基本となる考え方。"},{"word":"熱中症","meaning":"暑い環境で体温調節がうまくいかなくなり、めまい・頭痛・吐き気などを起こす障害。こまめな水分・塩分補給と休憩、WBGT（暑さ指数）を目安にした活動の調整で予防する。"},{"word":"RICE処置","meaning":"スポーツ外傷の応急処置の原則。安静（Rest）・冷却（Ice）・圧迫（Compression）・挙上（Elevation）の頭文字をとったもの。けがの直後に行うことで悪化を防ぐ。"},{"word":"ウォーミングアップ","meaning":"運動の前に体を温め、心拍数や筋肉の働きを少しずつ高める準備運動。けがの予防や運動効果の向上に役立つ。運動後のクーリングダウンと対になる。"},{"word":"落雷への対応","meaning":"雷鳴が聞こえたら屋外の活動をただちに中止し、建物の中など安全な場所に避難する。木の下や高い場所は危険なので避ける。"},{"word":"AED","meaning":"自動体外式除細動器。心臓が細かく震えて血液を送れない状態のときに電気ショックを与え、正常な動きに戻すための機器。公共施設や学校などに設置されている。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"体育","topic":"スポーツ外傷・障害","intro":"スポーツで起こるけがには、一度の大きな外力で起こる「スポーツ外傷」と、使いすぎによって少しずつ痛みが出る「スポーツ障害」の2種類があります。両者の違いと主な原因を知ることで、予防の方法も見えてきます。このテーマでは、代表的な外傷・障害の名前と、その予防のポイントを押さえましょう。","keywords":[{"word":"スポーツ外傷","meaning":"一度の大きな外力で起こる急性のけが。捻挫・骨折・脱臼・打撲・肉離れなどが代表例。"},{"word":"スポーツ障害","meaning":"同じ動作の繰り返しなどによる使いすぎ（オーバーユース）で起こる慢性のけがや痛み。野球肘・テニス肘・シンスプリント・疲労骨折など。"},{"word":"オーバーユース","meaning":"使いすぎのこと。特定の部位に負荷が繰り返し加わり続けることで、スポーツ障害の主な原因となる。"},{"word":"疲労骨折","meaning":"一度に折れるほどの力ではなく、弱い力が骨の同じ部位に繰り返し加わることで起こる骨折。ランニングやジャンプの多い競技で起こりやすい。"},{"word":"シンスプリント","meaning":"すねの内側に痛みが出る代表的なスポーツ障害。走る動作の繰り返しが主な原因で、初心者ランナーなどに多い。"},{"word":"障害の予防","meaning":"練習量の調整、正しいフォームの習得、筋力・柔軟性の向上、痛みをがまんしないことなどが障害予防の柱になる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"体育","topic":"健康づくりのための運動","intro":"運動は体力を高めるだけでなく、生活習慣病の予防や心の健康にも役立ちます。健康づくりのためには、運動の種類や強さ、続ける工夫を知ることが大切です。このテーマでは、有酸素運動の特徴、国の身体活動基準の目安、ロコモティブシンドロームやサルコペニアといった加齢にともなう変化への備えを押さえましょう。","keywords":[{"word":"有酸素運動","meaning":"ウォーキングやジョギングのように、酸素を取り入れながら比較的長く続けられる運動。脂肪をエネルギーとして使いやすく、生活習慣病の予防に役立つ。"},{"word":"身体活動基準","meaning":"国が示す健康づくりのための目安。18〜64歳では、3メッツ以上の身体活動を毎日60分行うことが勧められている。"},{"word":"メッツ","meaning":"身体活動の強さを表す単位。安静時を1メッツとし、普通の歩行が3メッツ程度。活動の強さと時間を組み合わせて活動量を考える。"},{"word":"ロコモティブシンドローム","meaning":"骨・関節・筋肉などの運動器の障害によって、立つ・歩くなどの移動機能が低下した状態。略してロコモ。将来の要介護リスクを高める。"},{"word":"サルコペニア","meaning":"加齢にともなう筋肉量の減少や筋力の低下。筋力トレーニングと十分なたんぱく質の摂取が予防に役立つ。"},{"word":"メタボリックシンドローム","meaning":"内臓脂肪の蓄積（腹囲が男性85cm以上・女性90cm以上）に加え、高血糖・脂質異常・高血圧などが重なった状態。生活習慣病のリスクが高い。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"体育","topic":"生涯スポーツ","intro":"スポーツは、学校を卒業したら終わりというものではありません。子どものころから高齢になるまで、年齢や体力に合わせて形を変えながら楽しみ続けることができます。このテーマでは、生涯スポーツの考え方、「する・みる・ささえる」という多様な関わり方、総合型地域スポーツクラブやスポーツ基本法など、それを支える仕組みを押さえましょう。","keywords":[{"word":"生涯スポーツ","meaning":"生涯にわたって、それぞれの年齢・体力・興味に応じてスポーツに親しみ続けること、またその考え方。"},{"word":"する・みる・ささえる","meaning":"スポーツへの関わり方の3つの形。自分でプレーする「する」、観戦する「みる」、ボランティアや指導などで支える「ささえる」。"},{"word":"総合型地域スポーツクラブ","meaning":"地域住民が主体となって運営し、子どもから高齢者までが複数の種目を楽しめるスポーツクラブ。地域のスポーツの受け皿として各地に広がっている。"},{"word":"ライフステージ","meaning":"人生の段階のこと（少年期・青年期・壮年期・高齢期など）。段階ごとに体力や生活が変わるため、スポーツの形も合わせていく。"},{"word":"スポーツ基本法","meaning":"スポーツに関する基本的な理念と国の責務などを定めた法律。スポーツを通じて幸福で豊かな生活を営むことを人々の権利としている。"},{"word":"スポーツ庁","meaning":"国のスポーツ行政を担当する機関。スポーツの振興に関する政策を進めている。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"体育","topic":"ライフスタイルに応じたスポーツ","intro":"運動を続けられるかどうかは、意志の強さだけでなく、自分の生活に合った形で取り入れられるかどうかに大きく左右されます。このテーマでは、自分の生活リズムや体力を把握することから始めて、目標の設定、すきま時間の活用、計画の見直しまで、自分に合ったスポーツライフを設計する手順を押さえましょう。","keywords":[{"word":"ライフスタイル","meaning":"日常生活の送り方や習慣、価値観などの総体。生活様式。スポーツは自分のライフスタイルに合わせて取り入れることで続けやすくなる。"},{"word":"スポーツライフの設計","meaning":"自分の現状（生活時間・体力・興味）を把握し、目標と計画を立て、実践と見直しを繰り返しながら、自分に合ったスポーツとの関わり方を作っていくこと。"},{"word":"現状の把握","meaning":"設計の出発点。1日の生活時間、体力、健康状態、興味のある種目などを知ること。"},{"word":"目標設定","meaning":"「週に2回、30分歩く」のように、具体的で、現状から少し頑張れば届く水準の目標を立てることが継続のポイントになる。"},{"word":"すきま時間の活用","meaning":"徒歩での移動や階段の利用など、日常生活の中の活動を積み重ねて活動量を増やす工夫。まとまった時間がとれない人にも有効。"},{"word":"PDCAサイクル","meaning":"計画（Plan）・実行（Do）・評価（Check）・改善（Action）を繰り返す進め方。計画の見直しに役立つ。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"体育","topic":"スポーツ推進の取り組み","intro":"スポーツを楽しめる環境は、自然にできるものではなく、国や地方公共団体、学校、地域、企業など、さまざまな主体の取り組みによって支えられています。このテーマでは、スポーツ庁や総合型地域スポーツクラブ、スポーツボランティア、障がい者スポーツの推進、スポーツツーリズムなど、スポーツを広げる取り組みを押さえましょう。","keywords":[{"word":"スポーツ庁","meaning":"国のスポーツ行政を担当する機関（2015年設置）。スポーツ立国の実現に向けた政策を進めている。"},{"word":"総合型地域スポーツクラブ","meaning":"地域住民が主体となり、世代をこえて複数の種目を楽しめるクラブ。地域のスポーツ推進の中心的な存在。"},{"word":"スポーツボランティア","meaning":"大会の運営補助や観客の案内など、スポーツを「ささえる」立場で無償で活動する人。大会の成功に欠かせない。"},{"word":"障がい者スポーツ","meaning":"障がいのある人が行うスポーツ。推進することで、障がいの有無にかかわらずスポーツを楽しめる共生社会の実現につながる。"},{"word":"スポーツツーリズム","meaning":"スポーツの観戦や大会への参加を目的とした旅行と、地域の活性化を結びつけた取り組み。"},{"word":"レガシー","meaning":"大会開催などによって社会に残る遺産のこと。施設だけでなく、人々のスポーツへの関心や参加の広がりも含まれる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"体育","topic":"豊かなスポーツライフの創造","intro":"スポーツの価値は、勝つことや記録を伸ばすことだけではありません。健康づくり、楽しさ、仲間との交流、自然との関わりなど、多様な価値が私たちの生活を豊かにしてくれます。このテーマでは、フェアプレイやドーピングの問題も含めて、生涯にわたる豊かなスポーツライフを自分で作っていく考え方を押さえましょう。","keywords":[{"word":"スポーツの多様な価値","meaning":"健康の維持・増進、楽しさ、仲間との交流、挑戦と達成感、地域とのつながりなど、スポーツが持つさまざまな価値。"},{"word":"フェアプレイ","meaning":"ルールを守り、相手や審判を尊重して正々堂々と競う態度。スポーツの土台となる精神。"},{"word":"ドーピング","meaning":"禁止薬物などを使って競技力を不公正に高める行為。公正さを損ない、健康を害するため厳しく禁止されている。"},{"word":"スポーツと交流","meaning":"スポーツは共通の楽しみを通じて、年齢・地域・国をこえた人々のつながりや連帯感を生み出す。"},{"word":"スポーツと環境","meaning":"自然の中で行うスポーツでは、環境を守る責任ある行動が求められる。活動の場を将来に残すこともスポーツライフの一部。"},{"word":"関わり方の変化","meaning":"年齢や興味の変化に合わせて、「する・みる・ささえる」の比重や種目を選び直していくことで、スポーツライフは豊かに続いていく。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"働くということ","intro":"論理国語I部の「働くということ」では、働くことの意味や、言葉と仕事の関わりを扱った評論を読みます。筆者は、働くことを単にお金を得る手段としてではなく、社会と関わり、自分を形作る営みとして捉え直そうとします。このテーマでは、教科書の評論を読むための土台として、「はじめに『言葉』がある」「楽しく働くこと、楽に働くこと」などの文章に共通する論点とキーワードを押さえましょう。","keywords":[{"word":"労働と仕事の違い","meaning":"「労働」が賃金を得るための活動として捉えられがちなのに対し、「仕事」は社会の中での役割や、自分自身の生き方と結びついた営みとして論じられることが多い。"},{"word":"言葉と仕事","meaning":"働く場面では、指示を理解し、相手に伝え、関係を作るために言葉が欠かせない。言葉は仕事の道具であると同時に、仕事の内容そのものを形作る。"},{"word":"楽しく働く／楽に働く","meaning":"教科書の文章で対比される視点。「楽（らく）」と「楽しさ」は同じではなく、働くことの価値は楽さだけでは測れない、という論点につながる。"},{"word":"社会との関わり","meaning":"働くことは、自分のためだけでなく、他者や社会に何かを提供する営みでもある。筆者の主張を読むとき、この視点が根拠として使われやすい。"},{"word":"筆者の主張の追い方","meaning":"評論では、具体例や対比の後に筆者の主張が置かれることが多い。「つまり」「だから」などの接続語と、段落の役割に注目して読む。"},{"word":"問いを立てる","meaning":"「なぜ働くのか」という大きな問いを、文章がどの部分でどう答えているかを意識して読む姿勢。評論読解の出発点になる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"論理の力―論理とは何か","intro":"教科書の「論理の力」では、論理とは何かを4つの力に分けて学びます。文章と文章を「つなぐ力」、根拠から「結論する力」、情報を「整理する力」、そして「質問する力」です。これらは評論文を読む力であると同時に、自分の考えを分かりやすく書く力でもあります。このテーマでは、4つの力の内容と、演繹・帰納などの基本的な考え方を押さえましょう。","keywords":[{"word":"つながる力","meaning":"文と文、段落と段落のつながり（因果・対比・言い換えなど）を読み取り、文章全体の流れを把握する力。"},{"word":"結論する力","meaning":"根拠をもとに結論を導く力。前提が正しくても、つなぎ方が誤っていれば結論は成り立たないことに注意する。"},{"word":"整理する力","meaning":"情報を分類したり、共通点と相違点を見つけたりして、物事を分かりやすく組み立て直す力。図や表への整理も含まれる。"},{"word":"質問する力","meaning":"文章や主張に対して「なぜか」「本当にそうか」と問いを立て、理解を深めたり問題点を見つけたりする力。"},{"word":"演繹（えんえき）","meaning":"一般的な前提から、個別の結論を導く推論の方法。例：「すべての人間は死ぬ。ソクラテスは人間である。ゆえにソクラテスは死ぬ。」"},{"word":"帰納（きのう）","meaning":"個別の事例を積み重ねて、一般的な法則や結論を導く推論の方法。事例の数や偏りに注意が必要になる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"科学と人間","intro":"論理国語II部の「科学と人間」では、人工知能やロボットを題材に、科学技術と人間の関わりを考える評論を読みます。石黒浩「鏡としての人工知能」では、人工知能の研究が人間自身への問いを映し出すことが論じられます。このテーマでは、科学技術をめぐる評論を読む土台として、人工知能を「鏡」と捉える見方や、人間と機械の境界をめぐる論点を押さえましょう。","keywords":[{"word":"鏡としての人工知能","meaning":"人工知能を作る・研究することは、人間の知能や心の仕組みを映し出し、人間とは何かを考え直すきっかけになる、という捉え方。"},{"word":"人工知能（AI）","meaning":"人間の知的活動をコンピュータで実現しようとする技術の総称。評論では、技術そのものより、それが人間観に与える影響が論点になることが多い。"},{"word":"ロボットと隣人","meaning":"ロボットが生活の中に入ってくるとき、人間はそれを道具としてだけでなく、関わりの相手として受け止めるようになる、という問題意識。"},{"word":"人間らしさの条件","meaning":"感情を持つこと、意識を持つこと、他者と関わることなど、「人間とは何か」をめぐる問いの軸。科学技術の発達によって問い直されている。"},{"word":"技術と倫理","meaning":"科学技術が可能にすることと、社会として許容できることの間には隔たりがある。評論では両者の関係が論じられる。"},{"word":"比喩の読み取り","meaning":"「鏡」のような比喩は、筆者の主張の核になることが多い。何を何にたとえ、どんな性質に注目しているかを読み取ることが大切。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"言葉と認識","intro":"論理国語II部の「豊かな認識」では、言葉と世界の捉え方の関係を考える評論を読みます。内田樹「言葉は『もの命名』ではない」は、言葉は物に名前を付けるだけの道具ではないと論じ、小川眞里子「科学的『発見』とは」は、科学における発見の意味を問い直します。このテーマでは、言葉が私たちの認識をどう形作るのかという論点と、発見をめぐる考え方を押さえましょう。","keywords":[{"word":"もの命名","meaning":"言葉は物に名前（ラベル）を付けるものだ、という考え方。内田樹はこの見方を批判し、言葉の働きはそれだけではないと論じる。"},{"word":"言葉と認識","meaning":"私たちは言葉を通して世界を切り分け、理解している。使う言葉が変われば、世界の見え方も変わる、という関係。"},{"word":"科学的発見","meaning":"未知のものを見つけること。小川眞里子の文章では、発見は単なる「発見」ではなく、既存の知識の枠組みとの関係の中で成り立つことが論じられる。"},{"word":"パラダイム","meaning":"ある時代の科学者集団が共有する、ものの見方や研究の枠組み。発見の評価はこの枠組みに左右される。"},{"word":"図解の読み解き方","meaning":"教科書でも扱われる技能。図やグラフが何を示し、何を示していないか、文章とどう対応するかを読み取ること。"},{"word":"常識を疑う","meaning":"評論の多くは、当たり前だと思われている見方に疑問を投げかけるところから始まる。問いの立て方に注目して読む。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"論理国語","topic":"知のゆくえと未来","intro":"論理国語II部の終盤「知のゆくえ」「明日をつくる」では、知識のあり方や、人類の未来を考える評論を読みます。吉見俊哉は知識の作為性と構造性を論じ、養老孟司は「もう一つの知性」を提示します。このテーマでは、知識は中立で固定的なものではなく、作られ、組み替えられていくものだという視点と、未来を考えるためのキーワードを押さえましょう。","keywords":[{"word":"知識の作為性","meaning":"知識は自然にそこにあるのではなく、人間が目的や関心に応じて作り出してきたものだ、という見方。"},{"word":"知識の構造性","meaning":"知識はばらばらの事実の集まりではなく、互いに関係し合い、体系として組み立てられているという性質。"},{"word":"もう一つの知性","meaning":"養老孟司が論じる、論理や計算だけではない知性のあり方。身体や感覚、都市と自然の対比などと結びつけて論じられる。"},{"word":"サピエンス","meaning":"現生人類（ホモ・サピエンス）のこと。若井京人の文章では、人類がどう自らを作り変えてきたかが論じられる。"},{"word":"未来のありか","meaning":"若林幹夫の文章の題名。未来はどこか遠くにあるのではなく、現在の私たちの営みの中にある、という問題意識と結びつく。"},{"word":"評論の総まとめの読み方","meaning":"終盤の文章は、それまでのテーマ（言葉・科学・認識）を踏まえて読むと理解が深まる。各文章の問いと主張を対応させて整理する。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"山月記","intro":"中島敦の「山月記」は、詩人を志しながら果たせず、虎になってしまった男・李徴の物語です。虎になった李徴が、友人の袁傪に自分の身の上を語る場面が中心で、「なぜ虎になったのか」をめぐる李徴自身の言葉が作品の核になります。このテーマでは、李徴の語る理由、臆病な自尊心と尊大な羞恥心という表現、そして中島敦の文章の特徴を押さえましょう。","keywords":[{"word":"李徴（りちょう）","meaning":"「山月記」の主人公。詩人として名を成そうとしたが挫折し、虎になってしまう。自分の変身の理由を冷静に分析して語る点が特徴。"},{"word":"袁傪（えんさん）","meaning":"李徴の友人。旅の途中で虎になった李徴と再会し、その告白を聞く聞き手の役割を担う。"},{"word":"臆病な自尊心と尊大な羞恥心","meaning":"李徴が自分を評した言葉。人に頭を下げることを恥とし、才能を世に問う勇気も持てなかった、という自己分析を表す。"},{"word":"虎になるということ","meaning":"作品の中心的なモチーフ。人間としての心を保ちながら姿が獣になることで、李徴の内面の問題が形になって表れている。"},{"word":"中島敦","meaning":"「山月記」の作者（1909〜1942）。中国の古典を題材にした作品が多く、格調高い文体で知られる。"},{"word":"一人称の告白","meaning":"李徴が自分の過去と心情を語る形式。語り手自身の解釈を通して読むため、その言葉をどこまで信じるかも読みどころになる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"こころ","intro":"夏目漱石の「こころ」は、先生と私の交流と、先生が抱え続けた過去の秘密を描いた長編小説です。作品は「上 先生と私」「中 両親と私」「下 先生と遺書」の三部で構成され、先生の遺書が後半の中心になります。このテーマでは、先生とKの関係、「精神的に向上心のないものは馬鹿だ」という言葉、明治の終わりという時代背景を押さえましょう。","keywords":[{"word":"先生","meaning":"「こころ」の中心人物。過去のある出来事をきっかけに人を信じられなくなり、孤独を抱えて生きている。"},{"word":"K","meaning":"先生の学生時代の友人。先生との関係の変化と、その結末が先生の生涯を決定づける。"},{"word":"遺書","meaning":"先生が「私」に宛てて残した長い手紙。「下 先生と遺書」の中心で、先生の過去と苦悩が明かされる。"},{"word":"エゴイズム","meaning":"自分の利益や感情を優先する心の働き。「こころ」は、人間のエゴイズムと、それに苦しむ良心を描いた作品として読まれる。"},{"word":"明治の精神","meaning":"作中で先生が口にする言葉。明治天皇の崩御や乃木大将の殉死と結びつき、時代の転換点としての明治の終わりが描かれる。"},{"word":"夏目漱石","meaning":"「こころ」の作者（1867〜1916）。『吾輩は猫である』『坊っちゃん』などでも知られる明治・大正の文豪。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"檸檬","intro":"梶井基次郎の「檸檬」は、得体の知れない憂鬱な気持ち（「えたいの知れない不快の塊」）を抱えた「私」が、京都の街を歩き、果物屋で買った一つの檸檬に心を動かされる短編です。あらすじの起伏よりも、感覚の描写と気持ちの変化が中心になります。このテーマでは、檸檬が「私」にとってどんな存在として描かれるか、色彩や感覚の表現を押さえましょう。","keywords":[{"word":"梶井基次郎","meaning":"「檸檬」の作者（1901〜1932）。短い生涯の中で、感覚的で詩情豊かな短編を残した。"},{"word":"えたいの知れない不快の塊","meaning":"「私」の心を重くする憂鬱な気持ちを表す作中の表現。原因のはっきりしない不快感が作品全体を覆う。"},{"word":"檸檬（レモン）","meaning":"「私」が果物屋で手に入れる一つの実。その色や重さ、冷たさが「私」の気持ちを一時的に晴らす象徴として描かれる。"},{"word":"丸善","meaning":"京都の書店。「私」がかつて好んだ場所だが、憂鬱な時期には入ることを避ける。作品の結末の舞台にもなる。"},{"word":"感覚の描写","meaning":"色・音・重さ・冷たさなど、五感に訴える描写が豊かなことが「檸檬」の文体の特徴。気持ちの変化が感覚を通して表される。"},{"word":"爆弾の比喩","meaning":"檸檬を丸善の書棚に置いて立ち去る場面で、「私」が空想するたとえ。憂鬱を吹き飛ばしたい気持ちの表れとして読める。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"舞姫","intro":"森鷗外の「舞姫」は、ドイツに留学した官僚の太田豊太郎が、踊り子のエリスと出会い、愛と出世の間で苦悩する物語です。文語体で書かれた初期の代表作で、近代化を進める明治日本と個人の感情の対立が描かれます。このテーマでは、豊太郎の選択とその後悔、エリスの人物像、そして作品が書かれた時代背景を押さえましょう。","keywords":[{"word":"森鷗外","meaning":"「舞姫」の作者（1862〜1922）。軍医としてドイツに留学した経験を持ち、その体験が作品の土台になっている。"},{"word":"太田豊太郎","meaning":"「舞姫」の主人公で語り手。エリート官僚として将来を嘱望されながら、エリスとの生活と出世の道の間で揺れる。"},{"word":"エリス","meaning":"ベルリンの踊り子。貧しい生活の中で豊太郎と出会い、共に暮らすようになる。"},{"word":"相沢謙吉","meaning":"豊太郎の友人。帰国と出世の道を豊太郎に勧め、物語の転換点に関わる人物。"},{"word":"文語体","meaning":"「舞姫」が書かれた、昔の書き言葉による文体。現代の口語体とは異なる格調が特徴で、教科書では現代語訳とあわせて学ぶこともある。"},{"word":"近代の自我","meaning":"個人の感情や生き方を大切にしたい気持ちと、国家や社会の期待との対立。「舞姫」は日本の近代文学における自我の問題を早くに描いた作品とされる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"随筆を読む","intro":"教科書には、随筆（エッセイ）がいくつも収められています。小池昌代「光の窓」、温又柔「国語から旅立って」、須賀敦子「クレールという女」など、作者の体験や記憶をもとに、自分の言葉で世界を見つめ直す文章です。このテーマでは、随筆という形式の特徴と、作者の視点の見つけ方、体験と感想の結びつきを押さえましょう。","keywords":[{"word":"随筆（エッセイ）","meaning":"作者が体験や見聞をもとに、感想や考えを自由な形式で書いた文章。小説のような作り話ではなく、書き手自身の視点が前面に出る。"},{"word":"書き手の視点","meaning":"随筆では、何を題材に選び、どこに注目するかに作者の個性が表れる。「なぜこの体験を取り上げたのか」を考えることが読みの手がかりになる。"},{"word":"体験と感想","meaning":"随筆は体験の記録だけではなく、そこから生まれた感想や発見が中心になる。具体的な場面と、作者の言葉の対応を追って読む。"},{"word":"国語から旅立って","meaning":"温又柔の随筆。複数の言語の間で育った作者が、言葉と自分の居場所について考える文章。"},{"word":"クレールという女","meaning":"須賀敦子の随筆。イタリアで出会った女性との記憶を通して、人との出会いと別れを静かに描く。"},{"word":"光の窓","meaning":"小池昌代の随筆。日常の光景から出発して、記憶や感情の広がりを描く文章として教科書に収められている。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"文学国語","topic":"戯曲―父と暮せば","intro":"井上ひさしの戯曲「父と暮せば」は、広島の原爆で父を亡くした娘・美津江と、幽霊となって現れる父・竹造の二人だけが登場する芝居です。恋に臆病になる娘を、父が励まし続ける温かくも切ない物語で、広島の方言で書かれています。このテーマでは、戯曲という形式の読み方、二人の関係、そして作品に込められた「生き残った者の苦しみ」という主題を押さえましょう。","keywords":[{"word":"戯曲","meaning":"舞台で上演するために書かれた作品。登場人物の台詞（セリフ）と、場面や動作を示すト書きで構成される。"},{"word":"井上ひさし","meaning":"「父と暮せば」の作者（1934〜2010）。小説家・劇作家として、笑いと社会への視点をあわせ持つ作品を多く残した。"},{"word":"美津江","meaning":"「父と暮せば」の主人公の娘。原爆で父を失い、「自分だけが生き残って幸せになってはいけない」という思いを抱えている。"},{"word":"竹造","meaning":"美津江の父。原爆で亡くなったが、幽霊として娘の前に現れ、恋を後押ししようとする。"},{"word":"ト書き","meaning":"戯曲で、台詞以外の、場面の様子や人物の動作・表情などを記した部分。読み手はト書きから舞台の様子を想像する。"},{"word":"原爆文学","meaning":"原子爆弾の被害と、その後の人々の生を描いた文学の総称。「父と暮せば」は、被爆者の心の傷と回復を描いた作品として読まれる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"日本史","topic":"飛鳥・奈良時代と律令国家","intro":"6世紀末から8世紀にかけて、日本では天皇を中心とする国家づくりが進みました。聖徳太子の改革、大化の改新を経て、大宝律令の制定によって律令国家が成立し、平城京が都となります。このテーマでは、律令のしくみ、班田収授法と税の制度、そして白鳳文化・天平文化の特徴を押さえましょう。","keywords":[{"word":"聖徳太子（厩戸皇子）","meaning":"推古天皇のもとで摂政となり、十七条の憲法や冠位十二階を定め、天皇中心の国家づくりを進めた。"},{"word":"大化の改新","meaning":"645年、中大兄皇子と中臣鎌足らが蘇我氏を倒して始めた政治改革。公地公民の方針が示された。"},{"word":"律令","meaning":"律は刑罰の法、令は政治の仕組みを定めた法。中国の制度を手本に整えられ、大宝律令（701年）で本格的に成立した。"},{"word":"班田収授法","meaning":"戸籍に登録された人々に口分田を分け与え、死ねば国に返させる制度。律令国家の土地・人民支配の土台となった。"},{"word":"租・調・庸","meaning":"律令制の主な税。租は口分田の収穫の約3％の稲、調は地方の特産物、庸は都での労役の代わりに納める布。"},{"word":"天平文化","meaning":"奈良時代、唐との交流や仏教の影響を受けて栄えた国際的で華やかな文化。東大寺の大仏や正倉院の宝物が代表例。"}],"diagram":null,"illustration":null,"story_intro":"大陸の進んだ仕組みを学び、天皇を中心とする国を作ろうとした人々がいました。聖徳太子の改革、大化の改新を経て律令が整い、平城京の都が開かれます。班田収授法や租・調・庸といった税や土地の決まりが全国に広がり、仏教文化が花開く、国家づくりの物語を見ていきましょう。"},{"subject":"日本史","topic":"平安時代と摂関政治","intro":"794年の平安遷都から、平安時代が始まります。やがて藤原氏が天皇の外戚として権力を握る摂関政治が全盛となり、唐風から日本風へと文化が変化する国風文化が生まれました。このテーマでは、摂関政治のしくみ、遣唐使の停止と国風文化、そして『源氏物語』や『枕草子』などの女流文学を押さえましょう。","keywords":[{"word":"平安遷都","meaning":"794年、桓武天皇が都を平安京（京都）に移したこと。奈良時代の仏教勢力の影響を避ける目的もあったとされる。"},{"word":"摂関政治","meaning":"藤原氏が、天皇が幼いときは摂政、成人後は関白として政治の実権を握った政治の形。藤原道長・頼通のころに全盛となった。"},{"word":"藤原道長","meaning":"摂関政治の全盛期を築いた人物。「この世をば わが世とぞ思う 望月の…」の歌でも知られる。"},{"word":"国風文化","meaning":"遣唐使の停止（894年）などを背景に、日本の風土や感性に合った独自の文化。かな文字の発達がその土台となった。"},{"word":"かな文字","meaning":"漢字をもとに作られた日本独自の文字。ひらがな・カタカナの発達によって、日本語の文章や文学が大きく広がった。"},{"word":"源氏物語と枕草子","meaning":"紫式部『源氏物語』は長編物語、清少納言『枕草子』は随筆の代表作。宮廷に仕えた女性たちによって国風文化の文学が花開いた。"}],"diagram":null,"illustration":null,"story_intro":"京都に新しい都が開かれ、貴族たちの華やかな暮らしが始まります。藤原氏が天皇の親族として力を握る一方、唐風から日本風へと文化は姿を変え、かな文字で物語が書かれるようになりました。『源氏物語』や『枕草子』など、女性による文学も生まれました。宮廷の光と変化をたどる物語です。"},{"subject":"日本史","topic":"室町時代と戦国への歩み","intro":"南北朝の動乱を経て成立した室町幕府は、将軍と守護大名の力関係に左右される不安定な政権でした。日明貿易や室町文化が花開く一方、応仁の乱をきっかけに将軍の権威は衰え、戦国大名が各地に割拠する時代へと移っていきます。このテーマでは、室町幕府のしくみ、応仁の乱の意味、北山文化・東山文化の特徴を押さえましょう。","keywords":[{"word":"足利尊氏と室町幕府","meaning":"足利尊氏が京都に開いた幕府（1338年ごろ成立）。鎌倉幕府と比べ、将軍の力は守護大名の力に依存する面が大きかった。"},{"word":"南北朝の動乱","meaning":"後醍醐天皇の吉野の朝廷（南朝）と、足利氏の支える京都の朝廷（北朝）が対立した時代。1392年に南北朝は合一された。"},{"word":"足利義満と日明貿易","meaning":"3代将軍足利義満は明との勘合貿易を始め、北山文化を築いた。金閣（鹿苑寺金閣）がその象徴。"},{"word":"応仁の乱","meaning":"1467年に始まった内乱。守護大名同士の対立と将軍家の後継争いが重なり、京都を戦場にした。この乱の後、将軍の権威は大きく衰えた。"},{"word":"下剋上","meaning":"身分の低い者が実力で上の者を倒して地位を奪う風潮。戦国時代を象徴する言葉。"},{"word":"東山文化","meaning":"8代将軍足利義政のころの文化。銀閣、書院造、茶の湯や生け花のもとになる要素など、簡素で深みのある美意識が特徴。"}],"diagram":null,"illustration":null,"story_intro":"南北朝の動乱を経て室町幕府が成立しますが、将軍と守護大名の力関係は不安定でした。金閣や銀閣に象徴される文化が花開く一方、応仁の乱を境に将軍の権威は衰え、各地で実力者が台頭します。日明貿易も行われ、幕府の財政を支える役割を果たしました。戦国時代へつながる変化の物語です。"},{"subject":"日本史","topic":"江戸時代の社会と改革","intro":"江戸幕府の支配が安定すると、農業生産の拡大や貨幣経済の広がりによって社会は大きく変化しました。一方で、財政の苦しさや農村の変化に対して、享保の改革をはじめとする幕府の改革が繰り返し行われます。このテーマでは、身分制度と村のしくみ、三大改革の内容と結果、化政文化への流れを押さえましょう。","keywords":[{"word":"身分制度","meaning":"武士・百姓・町人などの身分が定められ、武士が支配層として政治を担ったしくみ。実際には身分の内側にも多様な立場があった。"},{"word":"村請制と五人組","meaning":"村ごとに税（年貢）をまとめて納めさせる村請制と、百姓同士が連帯責任を負う五人組の制度。村の自治と統制の両面を持った。"},{"word":"享保の改革","meaning":"8代将軍徳川吉宗の改革。目安箱の設置、上米の制、公事方御定書の制定などを行い、幕府財政の立て直しを図った。"},{"word":"田沼意次と寛政の改革","meaning":"田沼意次は商業を重視して財政の改善を図ったが、わいろ政治への批判も受けた。その後の松平定信の寛政の改革は、倹約と風紀の取り締まりを進めた。"},{"word":"天保の改革","meaning":"水野忠邦による改革。株仲間の解散や人返し令などを出したが、十分な成果を上げられず、幕府の衰えをあらわす結果となった。"},{"word":"化政文化","meaning":"江戸時代後期、江戸を中心に栄えた町人文化。歌川広重や葛飾北斎の浮世絵、川柳や滑稽本などが広く親しまれた。"}],"diagram":null,"illustration":null,"story_intro":"幕府の支配が安定すると、農業や商業が発展し社会は変化していきます。しかし財政の苦しさや農村の変化に、幕府は改革を繰り返して応えました。享保の改革をはじめ、幕府は立て直しの試みを繰り返しました。身分制度と村の仕組み、三大改革の試み、そして町人の文化が広がる時代の物語です。"},{"subject":"日本史","topic":"立憲政治と日清・日露戦争","intro":"1889年に大日本帝国憲法が発布され、翌年には帝国議会が開かれて、日本は立憲政治の時代に入りました。同時期に日清戦争・日露戦争を経験し、日本の国際的な地位は大きく変化します。このテーマでは、憲法と議会のしくみ、条約改正の達成、日清・日露両戦争の経過とその影響を押さえましょう。","keywords":[{"word":"大日本帝国憲法","meaning":"1889年発布の明治憲法。天皇が主権者とされ、国民の権利は「法律の留保」のもとで認められた。"},{"word":"帝国議会","meaning":"貴族院と衆議院からなる議会。1890年に開設された。当初の衆議院議員の選挙権は、直接国税15円以上を納める25歳以上の男性に限られた。"},{"word":"条約改正","meaning":"幕末に結ばれた不平等条約の改正。1894年に領事裁判権の撤廃、1911年に関税自主権の回復を達成した。"},{"word":"日清戦争","meaning":"1894〜95年、朝鮮半島の支配をめぐる日本と清の戦争。下関条約で日本は遼東半島・台湾などを得たが、三国干渉で遼東半島は返還した。"},{"word":"日露戦争","meaning":"1904〜05年、満州と朝鮮の権益をめぐる日本とロシアの戦争。ポーツマス条約で講和したが、日本は賠償金を得られなかった。"},{"word":"産業革命の進展","meaning":"日清戦争前後から軽工業、日露戦争前後には重工業も発展し、日本の資本主義が本格化した時期。"}],"diagram":null,"illustration":null,"story_intro":"大日本帝国憲法が発布され、帝国議会が開かれて立憲政治が始まります。条約改正を成し遂げる一方、日本は日清戦争・日露戦争を経験し、国際的な地位を変えていきました。不平等条約の改正も、この時期に成し遂げられました。産業革命も進む、近代国家としての歩みの物語です。"},{"subject":"日本史","topic":"大正デモクラシーと両大戦間期","intro":"第一次世界大戦後の日本では、政党政治が発展し、普通選挙法が成立するなど、大正デモクラシーと呼ばれる民主主義の広がりが見られました。都市化や大衆文化も進みますが、1929年の世界恐慌をきっかけに社会は不安定になっていきます。このテーマでは、政党内閣の時代、普通選挙と治安維持法の同時成立、そして恐慌への流れを押さえましょう。","keywords":[{"word":"大正デモクラシー","meaning":"大正時代を中心に広がった、民主主義を求める思想や運動の総称。吉野作造の民本主義がその代表的な理論。"},{"word":"政党内閣","meaning":"議会で多数を占める政党の党首が内閣を組織する政治の形。原敬内閣（1918年）が本格的な政党内閣の始まりとされる。"},{"word":"普通選挙法","meaning":"1925年成立。納税額による制限がなくなり、25歳以上の男性に選挙権が与えられた。ただし女性にはまだ選挙権がなかった。"},{"word":"治安維持法","meaning":"普通選挙法と同年に制定された法律。天皇制や私有財産制を否定する運動を取り締まるもので、後に思想弾圧の道具となっていった。"},{"word":"世界恐慌","meaning":"1929年、アメリカの株価暴落から始まった世界的な不況。日本では昭和恐慌として、農村や都市の生活を直撃した。"},{"word":"大衆文化の広がり","meaning":"ラジオ放送の開始、映画、雑誌など、都市を中心に大衆向けの文化が広がった時期。生活様式も大きく変化した。"}],"diagram":null,"illustration":null,"story_intro":"第一次世界大戦後の日本では政党政治が発展し、普通選挙法が成立するなど民主主義が広がります。都市では大衆文化が花開きましたが、世界恐慌をきっかけに社会は不安定になっていきます。政党内閣の時代が続き、都市化も進んでいきました。希望と不安が交わる時代の物語です。"},{"subject":"日本史","topic":"戦後の復興と高度経済成長","intro":"第二次世界大戦後の日本は、占領下の改革を経て独立を回復し、その後は世界でも例の少ない速さで経済成長を遂げました。朝鮮戦争による特需、高度経済成長期の産業の変化、人々の生活の豊かさと公害問題の深刻化が重なる時代です。このテーマでは、サンフランシスコ平和条約から高度経済成長の終わりまでの流れを押さえましょう。","keywords":[{"word":"サンフランシスコ平和条約","meaning":"1951年に調印された講和条約。翌1952年に発効し、日本は独立を回復した。同時に日米安全保障条約も結ばれた。"},{"word":"朝鮮戦争と特需","meaning":"1950年に始まった朝鮮戦争で、アメリカ軍向けの物資の注文（特需）が日本経済の復興を後押しした。"},{"word":"高度経済成長","meaning":"1950年代半ばから1970年代初めまでの、年平均10％前後の高い経済成長が続いた時期。鉄鋼・造船・自動車・家電などの産業が発展した。"},{"word":"三種の神器と3C","meaning":"高度成長期に普及した家電製品の呼び名。白黒テレビ・洗濯機・冷蔵庫が「三種の神器」、後にカラーテレビ・クーラー・自動車が「3C」と呼ばれた。"},{"word":"公害問題","meaning":"経済成長の影で深刻化した、水俣病・四日市ぜんそくなどの公害。1967年に公害対策基本法が制定され、四大公害裁判でも争われた。"},{"word":"石油危機（オイルショック）","meaning":"1973年、石油価格の急騰によって世界経済が混乱した出来事。日本の高度経済成長はこの時期に終わりを迎えた。"}],"diagram":null,"illustration":null,"story_intro":"独立を回復した日本は、朝鮮戦争の特需をきっかけに復興を進め、やがて高度経済成長を遂げます。暮らしは豊かになる一方で公害問題も深刻化し、石油危機で成長の時代は終わります。朝鮮戦争による特需が、復興を後押しする出発点となりました。変化の速い戦後社会の物語をたどりましょう。"},{"subject":"世界史","topic":"古代文明の出現","intro":"人類は農耕と牧畜を始めることで定住生活に入り、やがて川の流域に大きな文明が生まれました。メソポタミア、エジプト、インダス、黄河の四大文明は、それぞれ文字・法・暦・宗教などを発達させ、後の世界の土台を作りました。このテーマでは、各文明が生まれた地域と特徴、そして農耕の始まりが社会をどう変えたかを押さえましょう。","keywords":[{"word":"農耕の始まり","meaning":"約1万年前、西アジアで始まったとされる。食料生産の開始は定住生活を生み、社会の分業や格差の出発点となった。"},{"word":"メソポタミア文明","meaning":"ティグリス川とユーフラテス川の流域に生まれた文明。楔形文字、ハンムラビ法典、太陰暦や六十進法で知られる。"},{"word":"エジプト文明","meaning":"ナイル川の定期的な氾濫を利用した文明。ファラオを頂点とする統一国家が長く続き、ピラミッドや太陽暦を残した。"},{"word":"インダス文明","meaning":"インダス川流域の都市文明。モヘンジョ＝ダロなどの計画都市と、整った排水設備が特徴。文字はまだ解読されていない。"},{"word":"黄河文明と殷","meaning":"黄河流域では仰韶文化などを経て、殷（商）が成立。青銅器と漢字のもとになる甲骨文字が使われた。"},{"word":"文明の共通点","meaning":"大河流域に生まれ、灌漑農業、文字、金属器、都市と国家の形成という共通の要素を持つ点が比較のポイントになる。"}],"diagram":null,"illustration":null,"story_intro":"乾いた大地に、やがて人々が種をまき始めた。農耕と牧畜によって定住の暮らしが生まれ、大河のほとりには大きな町が育っていく。メソポタミア、エジプト、インダス、黄河――四大文明はそれぞれ文字や法、暦や宗教を発達させ、後の世界の土台を作った。川の恵みが人々の社会をどう変えたのか、その物語をたどってみよう。"},{"subject":"世界史","topic":"イスラーム世界の成立と拡大","intro":"7世紀、アラビア半島でムハンマドがイスラーム教を開くと、その勢力は急速に西アジアから北アフリカ、イベリア半島へと広がりました。ウマイヤ朝・アッバース朝のもとで大帝国が築かれ、バグダードを中心に学問や文化も栄えます。このテーマでは、イスラーム教の教えの基本、カリフと王朝の移り変わり、拡大の理由を押さえましょう。","keywords":[{"word":"ムハンマド","meaning":"イスラーム教の開祖（預言者）。メッカで迫害を受け、622年にメディナへ移住した（ヒジュラ）。この年がイスラーム暦の元年となる。"},{"word":"コーランと六信五行","meaning":"聖典はコーラン（クルアーン）。信仰の基本は、唯一神アッラーへの信仰や礼拝・喜捨・断食・巡礼などの五行とされる実践。"},{"word":"カリフ","meaning":"預言者の後継者としてイスラーム共同体（ウンマ）を率いる指導者の称号。正統カリフ時代の後、ウマイヤ朝が世襲化した。"},{"word":"ウマイヤ朝","meaning":"ダマスカスを都とした王朝（661〜750）。イベリア半島まで領土を広げたが、アラブ人優遇への不満が高まった。"},{"word":"アッバース朝","meaning":"バグダードを都とした王朝（750〜1258）。イスラーム世界の交易と学問の中心となり、『千夜一夜物語』の舞台としても知られる。"},{"word":"拡大の背景","meaning":"ビザンツ帝国とサーサーン朝ペルシアの衰え、被支配層への寛容さや税制などが、急速な拡大を支えたとされる。"}],"diagram":null,"illustration":null,"story_intro":"7世紀、アラビア半島の町メッカに一人の預言者が現れた。ムハンマドが開いたイスラーム教は、やがて西アジアから北アフリカ、イベリア半島へと驚くほどの速さで広がっていく。ウマイヤ朝とアッバース朝の大帝国のもと、バグダードでは学問や文化も栄えた。その拡大の物語と理由を追ってみよう。"},{"subject":"世界史","topic":"南アジアと東南アジアの世界","intro":"南アジアでは、グプタ朝のもとでヒンドゥー教文化が花開き、やがてイスラーム勢力も進出しました。東南アジアはインドと中国を結ぶ海の交易路の要地として栄え、海域に根ざした独自の国家や文化を育てます。このテーマでは、インド世界の広がり方と、東南アジアの海のネットワーク、代表的な国家や文化を押さえましょう。","keywords":[{"word":"グプタ朝","meaning":"4〜6世紀の北インドの王朝。ヒンドゥー教が社会の中心となり、サンスクリット文学や数学（ゼロの概念）などが発展した。"},{"word":"ヒンドゥー教の形成","meaning":"バラモン教が民間信仰と結びついて成立したインドの宗教。カースト制と結びつき、人々の生活に深く根づいた。"},{"word":"デリー＝スルタン朝","meaning":"13世紀に北インドに成立したイスラーム王朝。イスラーム教がインドに広がるきっかけとなった。"},{"word":"シュリーヴィジャヤ","meaning":"スマトラ島を中心にマラッカ海峡の交易を支配した海の王国。海運の要地を押さえて繁栄した。"},{"word":"アンコール朝","meaning":"カンボジアに栄えた王朝。アンコール＝ワットに代表される壮大なヒンドゥー・仏教建築を残した。"},{"word":"海の道と交易","meaning":"東南アジアは香辛料などの産地であり、インド洋と南シナ海を結ぶ中継地。交易を通じてインドや中国の文化が伝わり、地域の文化と融合した。"}],"diagram":null,"illustration":null,"story_intro":"大きな川が流れる南アジアでは、グプタ朝のもとでヒンドゥー教の文化が花開き、やがてイスラームの勢力も進出してきた。一方、インドと中国を結ぶ海の道では、交易で栄える国々が次々に生まれる。陸と海、二つの世界がどのようにつながり、独自の国家や文化を育てたのかをたどってみよう。"},{"subject":"世界史","topic":"モンゴル帝国とユーラシア","intro":"13世紀初め、チンギス＝ハンがモンゴル高原の遊牧民を統一すると、その勢力はユーラシア大陸の広い範囲を支配する帝国へと成長しました。元の成立によって中国もその一部となり、大陸を横断する交易や人の移動が活発になります。このテーマでは、帝国の拡大の過程、分裂後のハン国、元の中国支配とその終わりを押さえましょう。","keywords":[{"word":"チンギス＝ハン","meaning":"1206年にモンゴル民族を統一し、帝国を築いた指導者。優れた軍事組織と人材登用で急速に版図を広げた。"},{"word":"モンゴル帝国の拡大","meaning":"西夏・金への遠征に始まり、中央アジアや東ヨーロッパにまで及んだ。駅伝制（ジャムチ）の整備が広大な支配を支えた。"},{"word":"4ハン国","meaning":"帝国が分裂してできた、キプチャク＝ハン国、チャガタイ＝ハン国、イル＝ハン国、オゴタイ＝ハン国などの諸国家。"},{"word":"元（フビライ）","meaning":"チンギス＝ハンの孫フビライが建てた王朝（1271年国号を元とする）。南宋を滅ぼして中国を統一し、大都（北京）を都とした。"},{"word":"元の日本遠征","meaning":"1274年と1281年の二度にわたる元軍の襲来（元寇）。いずれも暴風雨などの影響もあって失敗に終わった。"},{"word":"ユーラシアの交流","meaning":"帝国の支配のもとで東西の交易路が結ばれ、物産・技術・宗教などが大陸規模で移動した。マルコ＝ポーロの旅行記もこの時代のもの。"}],"diagram":null,"illustration":null,"story_intro":"13世紀初め、草原の遊牧民を一人の指導者が統一した。チンギス＝ハンの登場である。その勢力はやがてユーラシア大陸の広い範囲を支配する帝国へと成長し、中国も元としてその一部になった。大陸を横断する交易や人の移動が活発になるなか、世界はどう変わっていったのか。その大きな物語を見ていこう。"},{"subject":"世界史","topic":"主権国家体制と宗教改革","intro":"16世紀のヨーロッパでは、宗教改革がキリスト教世界を揺るがし、やがて宗教対立を乗り越える形で主権国家が並び立つ体制が形作られました。三十年戦争の講和であるウェストファリア条約は、その転換点とされます。このテーマでは、ルターとカルヴァンの改革、対抗宗教改革、そして主権国家体制の意味を押さえましょう。","keywords":[{"word":"ルターの宗教改革","meaning":"1517年、ルターが「九十五か条の論題」を発表し、贖宥状（免罪符）の販売を批判。信仰のみ・聖書のみを掲げ、プロテスタントが生まれた。"},{"word":"カルヴァンと予定説","meaning":"ジュネーヴで神政政治を行ったカルヴァンの改革。救済はあらかじめ定められているとする予定説を説き、勤勉な生活が重視された。"},{"word":"イギリス国教会","meaning":"ヘンリ8世が離婚問題をきっかけにカトリック教会から離脱して成立した教会。国王を首長とした。"},{"word":"対抗宗教改革","meaning":"カトリック側の改革運動。トリエント公会議で教義を明確化し、イエズス会などが布教と教育に力を入れた。"},{"word":"三十年戦争","meaning":"1618〜48年、神聖ローマ帝国内の宗教対立から始まり、ヨーロッパ諸国を巻き込んだ戦争。多くの被害を出した。"},{"word":"ウェストファリア条約","meaning":"1648年の講和条約。各国が対等な主権を持つとする主権国家体制の出発点とされ、宗教への不干渉も確認された。"}],"diagram":null,"illustration":null,"story_intro":"16世紀のヨーロッパで、教会への一つの批判が大陸全体を揺るがす嵐となった。ルターに始まる宗教改革はキリスト教世界を分け、長い宗教対立の時代が続く。やがて三十年戦争の講和であるウェストファリア条約によって、主権国家が並び立つ体制が形作られた。対立を乗り越えるまでの物語を追ってみよう。"},{"subject":"世界史","topic":"世界市場の形成と植民地化","intro":"19世紀後半、産業資本主義が発展したヨーロッパ列強は、原料の供給地と製品の市場を求めてアジア・アフリカへ進出し、世界は列強によって分割されていきます。西アジアの改革、南アジア・東南アジアの植民地化、中国の半植民地化が同時進行しました。このテーマでは、世界市場の形成の仕組みと、各地域の植民地化と抵抗の動きを押さえましょう。","keywords":[{"word":"産業資本主義","meaning":"産業革命後の資本主義の段階。工場制機械工業を基盤に、資本の蓄積と市場の拡大が進んだ。"},{"word":"インド大反乱とイギリス領インド","meaning":"1857年の大反乱（セポイの乱）の後、東インド会社は解散し、インドはイギリスの直接統治下に置かれた。"},{"word":"アヘン戦争","meaning":"1840〜42年と1856〜60年の二度にわたる戦争。清は敗れて開港と不平等条約を強いられ、半植民地化が進んだ。"},{"word":"オスマン帝国の改革","meaning":"西アジアでは、オスマン帝国がタンジマートと呼ばれる西洋化改革を進めたが、列強の圧力のもとで領土を失っていった。"},{"word":"アフリカ分割","meaning":"19世紀末、ヨーロッパ列強がアフリカ大陸を短期間のうちに植民地として分割した動き。ベルリン会議（1884〜85）でそのルールが話し合われた。"},{"word":"民族運動の始まり","meaning":"植民地化への抵抗として、インド国民会議の結成（1885）など、独立を求める民族運動が各地で生まれた。"}],"diagram":null,"illustration":null,"story_intro":"19世紀後半、産業の力を手にしたヨーロッパの列強は、原料と市場を求めて海を渡った。アジアやアフリカの各地が植民地となり、世界は列強によって分割されていく。西アジアの改革、中国の半植民地化、各地の抵抗の動きが同時進行した時代に、世界市場はどのように作られたのか。その物語を追おう。"},{"subject":"世界史","topic":"第二次世界大戦","intro":"世界恐慌を背景にファシズムや軍国主義が台頭し、国際協調の体制は崩れていきました。1939年、ドイツのポーランド侵攻をきっかけに第二次世界大戦が始まり、戦火はアジア・太平洋にも広がります。このテーマでは、戦争への道のり、戦争の拡大と転換点、そして戦後秩序の構想が始まるまでを押さえましょう。","keywords":[{"word":"ファシズムの台頭","meaning":"イタリアのムッソリーニ、ドイツのヒトラー（ナチス）など、独裁と民族主義を掲げる運動が恐慌後の不安の中で支持を広げた。"},{"word":"第二次世界大戦の開始","meaning":"1939年9月、ドイツがポーランドに侵攻し、英仏がドイツに宣戦布告して戦争が始まった。"},{"word":"日中戦争と太平洋戦争","meaning":"1937年に始まった日中戦争は長期化し、1941年に日本が真珠湾を攻撃して太平洋戦争が始まった。"},{"word":"ミッドウェー海戦とスターリングラード","meaning":"1942〜43年ごろの戦局の転換点。太平洋ではミッドウェー海戦、ヨーロッパ東部戦線ではスターリングラードの戦いが転機となった。"},{"word":"連合国の戦後構想","meaning":"大西洋憲章（1941）やヤルタ会談（1945）など、戦争のさなかから戦後の国際秩序の設計が進められた。"},{"word":"戦争の終結","meaning":"1945年、ドイツの降伏と、日本のポツダム宣言受諾によって戦争は終わった。一般市民を含む膨大な犠牲を出した戦争だった。"}],"diagram":null,"illustration":null,"story_intro":"世界恐慌の暗い影のなかで、ファシズムや軍国主義が台頭し、国際協調の体制は崩れていった。1939年、ドイツのポーランド侵攻をきっかけに再び世界大戦が始まり、戦火はアジア・太平洋にも広がる。戦争の拡大と転換点、そして戦後秩序の構想が始まるまでを、一つの大きな物語として追ってみよう。"},{"subject":"世界史","topic":"冷戦とその終結","intro":"第二次世界大戦後、アメリカを中心とする西側陣営と、ソ連を中心とする東側陣営が対立する冷戦の時代が始まりました。直接の全面戦争は避けられながらも、朝鮮戦争やキューバ危機など緊張の場面が続き、やがて1989年のマルタ会談と1991年のソ連解体で冷戦は終わります。このテーマでは、冷戦の始まり、緊張と緩和の波、そして終結の過程を押さえましょう。","keywords":[{"word":"冷戦","meaning":"米ソ両陣営が、直接の全面戦争を避けながら対立し続けた状態。核兵器の存在が全面戦争を抑止する一方、各地で代理戦争が起こった。"},{"word":"NATOとワルシャワ条約機構","meaning":"西側の軍事同盟がNATO（北大西洋条約機構、1949）、東側がワルシャワ条約機構（1955）。両陣営の対立を象徴する組織。"},{"word":"朝鮮戦争","meaning":"1950〜53年、朝鮮半島で南北が激突した戦争。アメリカ軍中心の国連軍と、中国の義勇軍が介入し、休戦協定のまま分断が固定された。"},{"word":"キューバ危機","meaning":"1962年、ソ連がキューバに核ミサイルを配備しようとして米ソが一触即発となった危機。交渉によって回避され、緊張緩和のきっかけにもなった。"},{"word":"ベトナム戦争","meaning":"アメリカが深く介入した戦争（本格介入は1960年代〜1975）。アメリカの敗北に終わり、その威信を大きく傷つけた。"},{"word":"冷戦の終結","meaning":"ゴルバチョフのペレストロイカ、1989年の東欧革命とベルリンの壁の崩壊、マルタ会談を経て、1991年にソ連が解体し冷戦は終わった。"}],"diagram":null,"illustration":null,"story_intro":"第二次世界大戦が終わると、アメリカを中心とする西側と、ソ連を中心とする東側がにらみ合う冷戦の時代が始まった。直接の全面戦争は避けられながらも、朝鮮戦争やキューバ危機など、緊張の場面が何度も訪れる。やがて1989年のマルタ会談と1991年のソ連解体で、この長い対立は終わりを迎えた。"},{"subject":"世界史","topic":"グローバル化と現代の課題","intro":"冷戦の終結後、人・物・お金・情報が国境をこえて行き交うグローバル化が急速に進みました。世界経済は結びつきを強める一方で、格差の拡大、環境問題、地域紛争や感染症など、一国では解決できない地球規模の課題も深刻になっています。このテーマでは、グローバル化の特徴と、現代世界が向き合う主な課題を押さえましょう。","keywords":[{"word":"グローバル化","meaning":"経済・文化・情報などが国境をこえて結びつき、相互依存が深まる動き。多国籍企業の活動や情報通信技術の発達が支えている。"},{"word":"WTOと自由貿易","meaning":"世界貿易機関（WTO、1995年発足）は自由貿易のルールを担う国際機関。地域経済統合（EUやASEANなど）も並行して進んだ。"},{"word":"南北問題と格差","meaning":"先進国と発展途上国の経済格差の問題。グローバル化の中でも格差の是正は大きな課題であり続けている。"},{"word":"地球環境問題","meaning":"地球温暖化、森林の減少、生物多様性の喪失など。パリ協定（2015）のように、国際的な協力の枠組みが作られている。"},{"word":"地域紛争と難民","meaning":"冷戦後も民族・宗教対立などによる紛争は続き、多くの難民が生まれている。人道支援と平和構築が課題となる。"},{"word":"SDGs","meaning":"持続可能な開発目標（2015年国連採択）。貧困や環境など17の目標を掲げ、2030年までの達成を目指す国際的な枠組み。"}],"diagram":null,"illustration":null,"story_intro":"冷戦が終わると、人・物・お金・情報が国境をこえて行き交うグローバル化が急速に進んだ。世界経済の結びつきが強まる一方で、格差の拡大、環境問題、地域紛争や感染症など、一国では解決できない課題も深刻になっている。私たちが生きる現代世界は、どのような特徴と課題を抱えているのだろう。"},{"subject":"倫理","topic":"人間の心のあり方","intro":"倫理の学びは、まず「人間とは何か」という問いから始まります。人間の特質、青年期の課題、そして認知や感情、発達といった心の働きを知ることは、自分自身を理解する手がかりになります。このテーマでは、人間を人間たらしめるもの、心の働きの基本、そして青年期に特有の課題を押さえましょう。","keywords":[{"word":"ホモ・サピエンスとホモ・ファーベル","meaning":"人間を表す言葉。ホモ・サピエンスは「知恵のある人」、ホモ・ファーベルは「作る人（工作人）」。道具の使用や言語が人間の特質とされる。"},{"word":"青年期の課題","meaning":"自分とは何かを問い（アイデンティティの確立）、親や社会の価値観を見直しながら、自立した自分の生き方を模索する時期の課題。"},{"word":"アイデンティティ","meaning":"「自分は自分である」という自己同一性の感覚。青年期の中心的な発達課題とされる（エリクソン）。"},{"word":"認知","meaning":"物事を知覚し、記憶し、考える心の働き。同じ出来事でも、認知のしかたによって受け止め方が変わる。"},{"word":"感情と知性","meaning":"感情は価値判断や行動の原動力となり、知性（理性）はそれを吟味し方向づける。両者のバランスが心のあり方を形作る。"},{"word":"発達","meaning":"人は生涯を通じて変化し続けるという見方。各時期に特有の課題（発達課題）があり、それに向き合うことで成長していく。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"倫理","topic":"中国の思想","intro":"古代中国では、孔子の儒家思想と、老子・荘子の道家（老荘）思想が生まれ、東アジアの人々の考え方に大きな影響を与えました。儒家は社会の秩序と人の道徳を重んじ、道家は人為を離れた自然のあり方を理想とします。このテーマでは、孔子と儒教の展開、孟子と荀子の対比、そして老荘思想の考え方を押さえましょう。","keywords":[{"word":"孔子と仁・礼","meaning":"儒家の開祖孔子は、思いやりの心である「仁」を内面の徳とし、それを社会の形にした「礼」を重んじた。『論語』にその言葉が残る。"},{"word":"儒教の展開","meaning":"漢の時代に国の教えとして採用され、科挙を通じて官僚の思想となり、やがて朝鮮や日本にも伝わって社会の規範となった。"},{"word":"孟子の性善説","meaning":"人間の本性は善であり、誰もが仁義の心の芽（四端）を持つとする考え方。王道政治と易姓革命の思想でも知られる。"},{"word":"荀子の性悪説","meaning":"人間の本性は悪に向かいやすいが、学びと礼によって正すことができる（化性起偽）とする考え方。孟子と対比される。"},{"word":"老子の無為自然","meaning":"人為的な行いを離れ、自然の流れにまかせる生き方（無為自然）を理想とした。『老子』（道徳経）にまとめられた。"},{"word":"荘子の万物斉同","meaning":"あらゆる物事の区別や価値は相対的であり、絶対的な視点から見れば等しいとする考え方。自由な境地（逍遥遊）を説いた。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"倫理","topic":"社会変革の思想と現代思想","intro":"19世紀、産業革命によって社会が大きく変わる中で、幸福の最大化を目指す功利主義、社会の仕組みそのものを変えようとする社会主義、より科学的な社会の見方を目指す実証主義などが生まれました。さらに20世紀には、理性中心の考え方への疑いから、実存主義や構造主義などの現代思想が展開します。このテーマでは、社会変革の思想の流れと、現代思想の代表的な考え方を押さえましょう。","keywords":[{"word":"功利主義","meaning":"行為の善悪を、その行為がもたらす幸福（快楽と苦痛の差）で判断する考え方。ベンサムの「最大多数の最大幸福」が有名。"},{"word":"ミルの功利主義","meaning":"J.S.ミルは、快楽には質の違いがあるとし、自由の尊重とあわせて功利主義を発展させた。『自由論』でも知られる。"},{"word":"社会主義思想","meaning":"生産手段の私有による格差や貧困を批判し、社会全体で富を分かち合う仕組みを目指す思想。マルクスの科学的社会主義が代表的。"},{"word":"実証主義","meaning":"コントが唱えた、観察と経験に基づく科学的な知識だけを確実なものとする考え方。社会学の出発点にもなった。"},{"word":"実存主義","meaning":"サルトルらが唱えた、人間はまず存在し、自分の選択と行動によって自分自身を作っていくとする考え方。「実存は本質に先立つ」が有名。"},{"word":"構造主義","meaning":"レヴィ＝ストロースらが展開した、人間の文化や思考の背後には無意識の構造があるとする考え方。現代思想に大きな影響を与えた。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"倫理","topic":"現代の諸課題と倫理","intro":"現代社会は、生命医療の進歩、環境問題、科学技術の発達、福祉のあり方、文化や宗教の多様性、戦争と平和など、答えが一つに定まらない倫理的な課題に直面しています。これらの課題に向き合うには、事実を知ることと、価値について考えることの両方が必要です。このテーマでは、各分野の代表的な論点と、考えるためのキーワードを押さえましょう。","keywords":[{"word":"生命倫理","meaning":"脳死と臓器移植、安楽死、出生前診断など、医療と生命をめぐる倫理的な問題を扱う分野。本人の意思（インフォームド・コンセント）が重視される。"},{"word":"環境倫理","meaning":"自然や将来世代に対する人間の責任を考える倫理。「将来世代への配慮」「自然の生存権」「地球全体を考える」などの原則が論じられる。"},{"word":"科学技術と倫理","meaning":"AIや遺伝子技術など、できることが増えるほど「やってよいか」を問う必要が生まれる。ヨーナスの責任倫理などが知られる。"},{"word":"福祉と正義","meaning":"社会保障や富の分配をどうすれば公正と言えるか。ロールズの「公正としての正義」などが、考える枠組みとして用いられる。"},{"word":"多文化共生","meaning":"文化や宗教の異なる人々が、互いの違いを認め合いながら共に生きること。現代の多様な社会における倫理の課題。"},{"word":"平和の実現","meaning":"戦争のない状態だけでなく、貧困や差別などの構造的暴力をなくす「積極的平和」（ガルトゥング）という考え方も重要になる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"民主政治の基本原理","intro":"民主政治は、人々の自由と平等を守りながら、社会の意思決定を行うための仕組みです。その土台には、権力の集中を防ぐ考え方や、基本的人権を保障する考え方があり、長い歴史の中で形作られてきました。このテーマでは、民主政治の成立の流れ、社会契約説や権力分立などの基本原理、そして世界のおもな政治体制の違いを押さえましょう。","keywords":[{"word":"国民主権","meaning":"国の政治のあり方を最終的に決める力（主権）は国民にあるという原理。民主政治の根本となる考え方。"},{"word":"社会契約説","meaning":"人々が契約によって国家を作ったとする考え方。ホッブズ、ロック、ルソーがそれぞれの立場から論じ、民主政治の理論的な土台となった。"},{"word":"権力分立","meaning":"国家の権力を立法・行政・司法に分け、互いに抑制し合うことで権力の乱用を防ぐ仕組み。モンテスキューが唱えた。"},{"word":"法の支配","meaning":"人も権力者も法に従うべきだという考え方。権力者の気まぐれな支配（人の支配）と対比される。"},{"word":"基本的人権の確立","meaning":"自由権を中心に、人権保障は市民革命を通じて確立され、やがて社会権なども含むようになった。"},{"word":"政治体制の違い","meaning":"民主主義体制のほか、権威主義体制や全体主義体制などがある。意思決定の方法と人権保障の有無が大きな違いになる。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"財政のしくみ","intro":"国や地方公共団体の活動は、税金などの収入（歳入）と、その使い道（歳出）からなる財政によって支えられています。財政には、景気を調整したり、所得の格差をやわらげたりする大切な役割があります。このテーマでは、租税の種類と原則、予算の仕組み、公債（国の借金）と財政の課題を押さえましょう。","keywords":[{"word":"財政の役割","meaning":"資源配分の調整（公共財の提供）、所得の再分配、景気の安定化の3つが財政の代表的な役割とされる。"},{"word":"直接税と間接税","meaning":"税を負担する人と納める人が同じなのが直接税（所得税など）、異なるのが間接税（消費税など）。両者のバランスが議論になる。"},{"word":"累進課税","meaning":"所得が多い人ほど高い税率が適用される仕組み。所得の再分配の役割を持つ。"},{"word":"予算と国会の議決","meaning":"政府が作る予算案は国会の議決を経て成立する。財政民主主義の表れであり、衆議院の優越も認められている。"},{"word":"公債（国債）","meaning":"国の支出が税収でまかなえないときに発行する借金。建設国債と、歳入不足を補う特例国債（赤字国債）がある。"},{"word":"財政の健全化","meaning":"公債残高の増大は将来世代への負担となるため、歳出の見直しや成長戦略などを通じて財政を立て直すことが課題となっている。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"日本経済の発展と課題","intro":"戦後の日本経済は、復興から高度経済成長を経て、世界有数の経済大国となりました。しかしその歩みの中では、公害問題、中小企業の課題、労働問題、社会保障の持続可能性など、さまざまな課題にも向き合ってきました。このテーマでは、戦後日本経済の流れと、雇用・労働、社会保障を中心とした現在の課題を押さえましょう。","keywords":[{"word":"高度経済成長","meaning":"1950年代半ばから1970年代初めまで続いた急速な経済成長。技術革新と設備投資、輸出の拡大が支えた。"},{"word":"バブル経済とその崩壊","meaning":"1980年代後半、地価や株価が実体以上に膨らんだバブル経済が1990年代初めに崩壊し、長期の景気低迷（失われた時代）につながった。"},{"word":"中小企業の課題","meaning":"日本企業の大半を占める中小企業は、大企業との生産性や賃金の格差、後継者不足などの課題を抱えている。"},{"word":"雇用と労働問題","meaning":"終身雇用や年功賃金といった日本的雇用慣行が変化し、非正規雇用の拡大、長時間労働、男女の格差などが課題となっている。"},{"word":"社会保障制度","meaning":"社会保険（医療・年金・介護など）、公的扶助、社会福祉、公衆衛生からなる、人々の生活を支える仕組み。"},{"word":"少子高齢化と社会保障","meaning":"現役世代の負担が重くなる中で、給付と負担のバランスをどう保つかが、社会保障の最大の課題となっている。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"国際政治と国際連合","intro":"国際社会には世界政府のような存在がなく、国家同士の関係は力関係や国際法、国際機関によって形作られています。第二次世界大戦後に設立された国際連合は、平和の維持と国際協力の中心的な機関ですが、その運営には課題も指摘されています。このテーマでは、国際政治の特質、国際法、国際連合の仕組みと課題、日本の役割を押さえましょう。","keywords":[{"word":"国際政治の特質","meaning":"国内政治と違い、世界全体を治める政府が存在しない。そのため、国家間の力関係や外交、国際法が重要な役割を果たす。"},{"word":"国際法","meaning":"条約と国際慣習法を主な法源とする、国家間の関係を規律する法。国内法のような強制力を持たない面もある。"},{"word":"国際連合の設立","meaning":"1945年、第二次世界大戦の反省から設立された国際機関。平和の維持と国際協力の推進を目的とする。"},{"word":"安全保障理事会","meaning":"国際の平和と安全の維持に主要な責任を持つ機関。アメリカ・イギリス・フランス・ロシア・中国の5常任理事国には拒否権がある。"},{"word":"PKO（平和維持活動）","meaning":"停戦の監視や選挙の支援などを行う国連の活動。日本も1992年のPKO協力法以降、要員を派遣してきた。"},{"word":"国際連合の課題","meaning":"常任理事国の拒否権による機能不全の指摘や、安保理の構成が現在の世界を反映していないという改革論議がある。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"政治・経済","topic":"国際経済とグローバル化","intro":"各国の経済は、貿易や投資を通じて深く結びついています。第二次世界大戦後、IMFやGATT・WTOを中心とする自由貿易の体制が築かれ、世界経済はグローバル化を進めてきました。このテーマでは、貿易と国際収支の基本、戦後国際経済体制の流れ、グローバル化がもたらす利益と課題を押さえましょう。","keywords":[{"word":"貿易の利益と比較優位","meaning":"各国が得意な財の生産に特化し貿易することで、全体の利益が増えるという考え方。リカードの比較生産費説が有名。"},{"word":"国際収支","meaning":"一国と外国との経済取引の記録。経常収支（貿易やサービスの収支など）が中心的な項目になる。"},{"word":"為替相場","meaning":"円とドルなど、通貨同士の交換比率。変動相場制のもとでは市場の需給で変動し、輸出入や物価に影響を与える。"},{"word":"IMFと世界銀行","meaning":"戦後の国際通貨体制を支える機関。IMFは国際通貨の安定、世界銀行は発展途上国への融資を主な役割とする。"},{"word":"GATTからWTOへ","meaning":"自由貿易を進める枠組みは、GATT（関税と貿易に関する一般協定）から、1995年にWTO（世界貿易機関）へと発展した。"},{"word":"グローバル化の課題","meaning":"経済の結びつきが深まる一方、国内産業への打撃や格差の拡大、環境問題などへの対応が課題となっている。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"情報","topic":"情報デザインとメディア","intro":"情報を伝えるためには、内容だけでなく「どう見せるか」が大切です。情報デザインは、受け手に分かりやすく伝わるよう、文字・色・配置などを工夫する考え方で、誰もが使いやすいユニバーサルデザインとも深く関わります。このテーマでは、情報デザインの基本、色や文字の使い方、メディアの特性と伝え方の工夫を押さえましょう。","keywords":[{"word":"情報デザイン","meaning":"情報を、受け手にとって分かりやすく使いやすい形に整理し、表現する工夫。目的と対象を意識することが出発点になる。"},{"word":"ユニバーサルデザイン","meaning":"年齢や障がいの有無などにかかわらず、できるだけ多くの人が利用できるように配慮した設計の考え方。"},{"word":"色の使い方と配色","meaning":"色には感情に訴える効果や、情報を区別する働きがある。色覚の多様性にも配慮し、色だけに頼らない表現が求められる。"},{"word":"文字と可読性","meaning":"文字の大きさ、書体、行間などの工夫によって読みやすさは大きく変わる。対象や媒体に合わせた選択が大切。"},{"word":"メディアの特性","meaning":"新聞・テレビ・Web・SNSなど、媒体ごとに伝わる速さ、情報量、双方向性が異なる。目的に合った媒体の選択が必要になる。"},{"word":"情報の流れの設計","meaning":"受け手が情報を得るまでの手順（導線）を考えること。Webページの構成や案内表示の設計などがその例。"}],"diagram":null,"illustration":null,"story_intro":null},{"subject":"情報","topic":"モデル化とシミュレーション","intro":"現実の世界は複雑で、そのままでは扱いにくいことが多くあります。そこで、物事の大切な要素だけを取り出して単純化する「モデル化」を行い、コンピュータ上で試す「シミュレーション」によって、予測や検証を行います。このテーマでは、モデル化の考え方、シミュレーションの手順と注意点、身近な活用例を押さえましょう。","keywords":[{"word":"モデル化","meaning":"現実の対象から、目的に必要な要素だけを取り出して単純化すること。地図や天気予報の計算モデルもその例。"},{"word":"シミュレーション","meaning":"モデルを使って、コンピュータ上で実験や予測を行うこと。実際には試せない条件も安全に検証できる。"},{"word":"乱数と確率的なモデル","meaning":"サイコロのように結果が確率で決まる現象は、乱数を使ったシミュレーション（モンテカルロ法など）で近似できる。"},{"word":"モデルの仮定","meaning":"モデルは現実を単純化しているため、置いた仮定によって結果が変わる。仮定を意識して結果を読む必要がある。"},{"word":"シミュレーションの活用例","meaning":"天気予報、交通の渋滞予測、災害時の避難計画、製品の設計など、社会のさまざまな場面で使われている。"},{"word":"結果の検証","meaning":"シミュレーションの結果は、実際のデータと比較して確かめることで信頼性が高まる。予測と現実のずれの原因を考えることも大切。"}],"diagram":null,"illustration":null,"story_intro":null}];
